"use client";

import type { FileViewerSidebarCollapsible } from "./file-viewer-context";
import type { FileViewerElements } from "./file-viewer-elements";

export type FileViewerSidebarAccessibilityProps = {
  "aria-hidden"?: true;
  inert?: true;
};

export type FileViewerSidebarTriggerAccessibilityProps = {
  "aria-controls"?: string;
  "aria-disabled"?: true;
  "aria-expanded"?: boolean;
  "aria-label": string;
};

const visibleSidebarAccessibilityProps = {};
const hiddenSidebarAccessibilityProps = {
  "aria-hidden": true,
  inert: true,
} as const;

export function resolveFileViewerSidebarAccessibilityProps({
  collapsible,
  deferInert,
  isSidebarInteractive,
}: {
  collapsible: FileViewerSidebarCollapsible;
  deferInert?: boolean;
  isSidebarInteractive: boolean;
}): FileViewerSidebarAccessibilityProps {
  if (collapsible === "none" || isSidebarInteractive) {
    return visibleSidebarAccessibilityProps;
  }

  if (deferInert) {
    return {
      "aria-hidden": true,
    };
  }

  return hiddenSidebarAccessibilityProps;
}

export function resolveFileViewerSidebarTriggerAccessibilityProps({
  ariaLabel,
  canToggleSidebar,
  isDisabled,
  isSidebarInteractive,
  sidebarId,
}: {
  ariaLabel: string;
  canToggleSidebar: boolean;
  isDisabled: boolean;
  isSidebarInteractive: boolean;
  sidebarId: string;
}): FileViewerSidebarTriggerAccessibilityProps {
  return {
    "aria-controls": canToggleSidebar ? sidebarId : undefined,
    "aria-disabled": isDisabled ? true : undefined,
    // Deliberately tracks interactivity, not the requested state: while the
    // panel slides open it is still inert, and announcing "expanded" would
    // point assistive tech at a region that cannot yet be used.
    "aria-expanded": canToggleSidebar ? isSidebarInteractive : undefined,
    "aria-label": ariaLabel,
  };
}

export function restoreFileViewerSidebarFocusOnClose({
  elements,
  isSidebarInteractive,
  previousIsSidebarInteractive,
}: {
  elements: FileViewerElements;
  isSidebarInteractive: boolean;
  previousIsSidebarInteractive: boolean;
}) {
  if (isSidebarInteractive || !previousIsSidebarInteractive) return;
  if (!elements.sidebarElement || !elements.sidebarTriggerElement) return;

  const ownerWindow = elements.sidebarElement.ownerDocument.defaultView;
  const activeElement = elements.sidebarElement.ownerDocument.activeElement;
  if (
    ownerWindow &&
    activeElement instanceof ownerWindow.HTMLElement &&
    elements.sidebarElement.contains(activeElement)
  ) {
    elements.sidebarTriggerElement.focus({ preventScroll: true });
  }
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

import {
  useOptionalFileViewerShellStatic,
  useFileViewerShellStatic,
} from "./file-viewer-context";
import {
  FileViewerDocumentFrameProvider,
  type FileViewerDocumentFrameState,
} from "./file-viewer-renderer-frame";
import { type FileViewerDocumentAlign } from "./file-viewer-renderer-contract";
import { useStableElementSize } from "./viewer-measurement";

const FileViewerContentContext = React.createContext(false);
const FileViewerInsetContext = React.createContext(false);
const FileViewerViewportContext = React.createContext(false);

export function useIsInsideFileViewerContent(): boolean {
  return React.useContext(FileViewerContentContext);
}

export function useIsInsideFileViewerInset(): boolean {
  return React.useContext(FileViewerInsetContext);
}

export function useIsInsideFileViewerViewport(): boolean {
  return React.useContext(FileViewerViewportContext);
}

export type FileViewerContentProps = React.ComponentProps<"div">;
export type FileViewerInsetProps = React.ComponentProps<"div"> & {
  align?: FileViewerDocumentAlign;
  documentFrameClassName?: string;
  documentFrameStyle?: React.CSSProperties;
  maxInlineSize?: React.CSSProperties["maxInlineSize"];
};
export type FileViewerLegendProps = React.ComponentProps<"div">;
export type FileViewerViewportProps = React.ComponentProps<"div">;

export function FileViewerContent({
  className,
  ...props
}: FileViewerContentProps) {
  const shell = useFileViewerShellStatic("FileViewerContent");

  return (
    <FileViewerContentContext.Provider value={true}>
      <div
        data-file-viewer-sidebar-mode={shell.mode}
        data-file-viewer-sidebar-side={shell.side}
        data-slot="file-viewer-content"
        className={cn(
          "relative flex min-h-0 min-w-0 flex-1 overflow-hidden",
          className,
        )}
        {...props}
      />
    </FileViewerContentContext.Provider>
  );
}

export function FileViewerLegend({
  className,
  ...props
}: FileViewerLegendProps) {
  return (
    <div
      data-slot="file-viewer-legend"
      className={cn("min-w-0 flex-shrink-0 border-b", className)}
      {...props}
    />
  );
}

export function FileViewerInset({
  align = "start",
  children,
  className,
  documentFrameClassName,
  documentFrameStyle,
  maxInlineSize,
  ...props
}: FileViewerInsetProps) {
  const shell = useOptionalFileViewerShellStatic();
  const hasAnimatedFileViewerWidth =
    shell?.mode === "inline" && shell.canToggleSidebar;
  const documentFrame = useMeasuredFileViewerDocumentFrame({
    enabled: !hasAnimatedFileViewerWidth,
  });
  const frame = React.useMemo<FileViewerDocumentFrameState>(
    () => ({
      align,
      element: documentFrame.element,
      inlineSize: documentFrame.inlineSize,
    }),
    [align, documentFrame.element, documentFrame.inlineSize],
  );

  return (
    <FileViewerInsetContext.Provider value={true}>
      <FileViewerDocumentFrameProvider value={frame}>
        <div
          data-slot="file-viewer-inset"
          className={cn(
            "relative flex h-full min-h-0 min-w-0 flex-1 flex-col overflow-hidden",
            className,
          )}
          {...props}
        >
          <div
            ref={documentFrame.setElement}
            data-slot="file-viewer-document-frame"
            className={cn(
              "[container-type:inline-size] relative flex h-full min-h-0 w-full min-w-0 flex-1 flex-col",
              getDocumentFrameAlignClass(align),
              documentFrameClassName,
            )}
            style={
              {
                maxInlineSize,
                ...documentFrameStyle,
              } as React.CSSProperties
            }
          >
            {children}
          </div>
        </div>
      </FileViewerDocumentFrameProvider>
    </FileViewerInsetContext.Provider>
  );
}

export const FileViewerViewport = React.forwardRef<
  HTMLDivElement,
  FileViewerViewportProps
>(function FileViewerViewport({ className, style, ...props }, ref) {
  const isInsideInset = useIsInsideFileViewerInset();
  const setElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      if (typeof ref === "function") {
        ref(element);
      } else if (ref) {
        ref.current = element;
      }
    },
    [ref],
  );

  if (process.env.NODE_ENV !== "production" && !isInsideInset) {
    throw new Error(
      "FileViewerViewport must be rendered inside FileViewerInset.",
    );
  }

  return (
    <FileViewerViewportContext.Provider value={true}>
      <div
        ref={setElement}
        data-slot="file-viewer-viewport"
        className={cn(
          "relative flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden",
          className,
        )}
        style={
          {
            ...style,
          } as React.CSSProperties
        }
        {...props}
      />
    </FileViewerViewportContext.Provider>
  );
});

function useMeasuredFileViewerDocumentFrame({ enabled }: { enabled: boolean }) {
  const size = useStableElementSize<HTMLDivElement>({
    enabled,
  });

  return React.useMemo(
    () => ({
      element: size.element,
      inlineSize: size.width,
      setElement: size.setElement,
    }),
    [size.element, size.setElement, size.width],
  );
}

function getDocumentFrameAlignClass(align: FileViewerDocumentAlign) {
  switch (align) {
    case "center":
      return "mx-auto";
    case "end":
      return "ml-auto";
    case "start":
      return "mr-auto";
  }
}

"use client";

import * as React from "react";

import type { FileCategory } from "@/lib/viewer-source";
import type { FileViewerElementRegistry } from "./file-viewer-elements";
import type { FileViewerMotionKernel } from "./file-viewer-motion-kernel";

export type FileViewerSidebarMode = "inline" | "overlay";
export type FileViewerSidebarRequestedMode = "auto" | FileViewerSidebarMode;
export type FileViewerSidebarState = "expanded" | "collapsed";
export type FileViewerSidebarSide = "left" | "right";
export type FileViewerSidebarCollapsible = "offcanvas" | "none";

export type FileViewerHeaderMode = "inline" | "outlets";

export const DEFAULT_FILE_VIEWER_SIDEBAR_WIDTH = "10rem";

export type FileViewerSetSidebarRequestedOpen = (
  value: boolean | ((isSidebarRequestedOpen: boolean) => boolean),
) => void;

export type FileViewerSidebarOpenProps = {
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  open?: boolean;
};

export type FileViewerContextValue = {
  headerMode: FileViewerHeaderMode;
  hasHeaderOutlets: boolean;
  isInsideFileViewer: boolean;
  resourceCategory: FileCategory;
  sidebarOpenProps: FileViewerSidebarOpenProps;
};

export type FileViewerSidebarRegistration = {
  collapsible: FileViewerSidebarCollapsible;
  id: string;
  side: FileViewerSidebarSide;
  width: string;
  widthPixels: number;
};

export type FileViewerSidebarStateValue = {
  canToggleSidebar: boolean;
  isSidebarInteractive: boolean;
  isSidebarRequestedOpen: boolean;
  mode: FileViewerSidebarMode;
  side: FileViewerSidebarSide;
  sidebarId: string;
  sidebarState: FileViewerSidebarState;
  setSidebarRequestedOpen: FileViewerSetSidebarRequestedOpen;
  toggleSidebarRequestedOpen: () => void;
};

export type FileViewerShellStaticContextValue = {
  canToggleSidebar: boolean;
  collapsible: FileViewerSidebarCollapsible;
  elementRegistry: FileViewerElementRegistry;
  mode: FileViewerSidebarMode;
  motionDurationMs: number;
  motionKernel: FileViewerMotionKernel;
  registerSidebar: (registration: FileViewerSidebarRegistration) => () => void;
  rootId: string;
  setSidebarRequestedOpen: FileViewerSetSidebarRequestedOpen;
  side: FileViewerSidebarSide;
  sidebarId: string;
  sidebarWidth: string;
  toggleSidebarRequestedOpen: () => void;
};

export type FileViewerSidebarDynamicContextValue = {
  isSidebarInteractive: boolean;
  isSidebarRequestedOpen: boolean;
  isSidebarTransitioning: boolean;
  sidebarState: FileViewerSidebarState;
};

export type FileViewerShellContextValue = FileViewerShellStaticContextValue &
  FileViewerSidebarDynamicContextValue;

export const FileViewerContext = React.createContext<FileViewerContextValue>({
  headerMode: "inline",
  hasHeaderOutlets: false,
  isInsideFileViewer: false,
  resourceCategory: "unsupported",
  sidebarOpenProps: {},
});

export const FileViewerShellStaticContext =
  React.createContext<FileViewerShellStaticContextValue | null>(null);

export const FileViewerSidebarDynamicContext =
  React.createContext<FileViewerSidebarDynamicContextValue | null>(null);

export function useFileViewerContext() {
  return React.useContext(FileViewerContext);
}

export function useOptionalFileViewerShellStatic() {
  return React.useContext(FileViewerShellStaticContext);
}

export function useFileViewerShellStatic(consumer: string) {
  const context = React.useContext(FileViewerShellStaticContext);
  if (!context) {
    throw new Error(`${consumer} must be rendered inside FileViewer.`);
  }
  return context;
}

export function useOptionalFileViewerShell() {
  const staticContext = React.useContext(FileViewerShellStaticContext);
  const sidebarContext = React.useContext(FileViewerSidebarDynamicContext);

  return React.useMemo(
    () =>
      staticContext && sidebarContext
        ? { ...staticContext, ...sidebarContext }
        : null,
    [sidebarContext, staticContext],
  );
}

export function useFileViewerShell(consumer: string) {
  const context = useOptionalFileViewerShell();
  if (!context) {
    throw new Error(`${consumer} must be rendered inside FileViewer.`);
  }
  return context;
}

export function useFileViewerSidebar(): FileViewerSidebarStateValue {
  const fileViewerContext = React.useContext(FileViewerContext);
  const shellContext = useOptionalFileViewerShell();

  if (!fileViewerContext.isInsideFileViewer || !shellContext) {
    throw new Error("useFileViewerSidebar must be used within FileViewer.");
  }

  return shellContext;
}

"use client";

import * as React from "react";

import type { ViewerControlsState } from "./viewer-controls";

export type FileViewerControlsState = ViewerControlsState;

type FileViewerControlsRegistration = {
  descriptorKey: string;
  state: FileViewerControlsState | null;
};

type FileViewerControlsValue = {
  controlsState: FileViewerControlsState | null;
};

const FileViewerControlsContext =
  React.createContext<FileViewerControlsValue | null>(null);

export function useFileViewerControlsController(descriptorKey: string): {
  controlsValue: FileViewerControlsValue;
  handleControlsChange: (state: FileViewerControlsState | null) => void;
} {
  const [controlsRegistration, setControlsRegistration] =
    React.useState<FileViewerControlsRegistration>(() => ({
      descriptorKey,
      state: null,
    }));
  const controlsState =
    controlsRegistration.descriptorKey === descriptorKey
      ? controlsRegistration.state
      : null;
  const handleControlsChange = React.useCallback(
    (state: FileViewerControlsState | null) => {
      setControlsRegistration({ descriptorKey, state });
    },
    [descriptorKey],
  );
  const controlsValue = React.useMemo<FileViewerControlsValue>(
    () => ({
      controlsState,
    }),
    [controlsState],
  );

  return {
    controlsValue,
    handleControlsChange,
  };
}

export function FileViewerControlsProvider({
  children,
  value,
}: {
  children: React.ReactNode;
  value: FileViewerControlsValue;
}) {
  return React.createElement(
    FileViewerControlsContext.Provider,
    { value },
    children,
  );
}

export function useFileViewerControlsState() {
  const context = React.useContext(FileViewerControlsContext);
  if (!context) {
    throw new Error("File viewer controls must be used within FileViewer.");
  }
  return context.controlsState;
}

import {
  detectCategory,
  extensionOf,
  extractName,
  resolveViewerDescriptor,
  textPayloadKey,
  type FileCategory,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source";

export type { FileCategory, ViewerSource };
export type FileViewerFallbackSize = { width: number; height: number };

export interface FileViewerCoreProps {
  source: ViewerSource;
  category?: FileCategory;
  className?: string;
  /** Intrinsic first-frame size for image/TIFF loading skeletons. */
  fallbackFrameSize?: FileViewerFallbackSize;
  /** Intrinsic first-slide size for PPTX loading skeletons. */
  fallbackSlideSize?: FileViewerFallbackSize;
  isolateStyles?: boolean;
}

export type FileDescriptor = ViewerDescriptor;

export function resolveFileDescriptor({
  source,
  category,
}: FileViewerCoreProps): FileDescriptor {
  return resolveViewerDescriptor({
    source,
    category,
  });
}

export function descriptorResetKey(descriptor: FileDescriptor): string {
  return [
    descriptorIdentityResetKey(descriptor),
    descriptor.displayName,
    descriptor.mimeType ?? "",
    descriptor.category,
  ].join("\u0000");
}

function descriptorIdentityResetKey(descriptor: FileDescriptor): string {
  if (
    descriptor.source.kind === "text" &&
    descriptor.source.identityKey == null
  ) {
    return textPayloadKey(descriptor.source.text);
  }
  return descriptor.identityKey;
}

export function isProseTextDescriptor(descriptor: FileDescriptor): boolean {
  if (descriptor.category !== "text") return false;

  const extension = extensionOf(descriptor.fileName);
  if (extension === "txt" || extension === "text") return true;
  return !extension && descriptor.mimeType?.toLowerCase() === "text/plain";
}

export { detectCategory, extensionOf, extractName };

export async function timed<T>(
  label: string,
  fn: () => Promise<T>,
): Promise<T> {
  const on =
    typeof globalThis !== "undefined" &&
    (globalThis as { __FILE_VIEWER_PROFILE__?: boolean })
      .__FILE_VIEWER_PROFILE__;
  if (!on) return fn();
  const t0 = performance.now();
  try {
    return await fn();
  } finally {
    console.log(
      `[file-viewer] ${label} ${(performance.now() - t0).toFixed(1)}ms`,
    );
  }
}

"use client";

import * as React from "react";

import { inferCsvDialect } from "@/lib/csv";
import { cn } from "@/lib/utils";
import type { ViewerResource } from "@/lib/viewer-resource";

const CsvResourceContent = React.lazy(() =>
  import("@/components/ui/csv-viewer").then((m) => ({
    default: m.CsvResourceContent,
  })),
);

export function CsvFileContent({
  resource,
  className,
  bare,
  controls = false,
  isolateStyles,
}: {
  resource: ViewerResource;
  className?: string;
  bare?: boolean;
  controls?: boolean;
  isolateStyles?: boolean;
}) {
  const dialect = inferCsvDialect({
    src: resource.content.directUrl ?? undefined,
    fileName: resource.fileName,
    mimeType: resource.mimeType,
  });
  return (
    <div
      data-slot="csv-file-viewer-content"
      className={cn(
        "bg-card flex min-h-0 flex-1 flex-col overflow-hidden",
        bare ? "h-full" : "min-h-64",
        className,
      )}
    >
      <CsvResourceContent
        resource={resource}
        dialect={dialect}
        fillHeight
        controls={controls}
        isolateStyles={isolateStyles}
      />
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

import { FileErrorBoundary, ViewerFallback } from "./file-viewer-fallback";
import { useFileViewerRequiredResourceState } from "./file-viewer-resource-state";
import { FileViewerRoute } from "./file-viewer-route";
import { useIsInsideFileViewerViewport } from "./file-viewer-content";

export type FileViewerDocumentProps = {
  className?: string;
  controls?: boolean;
};

export function FileViewerDocument({
  className,
  controls = false,
}: FileViewerDocumentProps) {
  const isInsideViewport = useIsInsideFileViewerViewport();

  if (process.env.NODE_ENV !== "production" && !isInsideViewport) {
    throw new Error(
      "FileViewerDocument must be rendered inside FileViewerViewport.",
    );
  }

  return (
    <FileViewerDocumentContent
      className={cn("h-full", className)}
      controls={controls}
    />
  );
}

function FileViewerDocumentContent({
  className,
  controls,
}: Required<Pick<FileViewerDocumentProps, "controls">> &
  Pick<FileViewerDocumentProps, "className">) {
  const {
    descriptor,
    descriptorKey,
    descriptorSignal,
    fallbackFrameSize,
    fallbackSlideSize,
    isClient,
    isolateStyles,
    resource,
  } = useFileViewerRequiredResourceState();
  const fallback = (
    <ViewerFallback
      resource={resource}
      className={className}
      bare
      controls={controls}
      fallbackFrameSize={fallbackFrameSize}
      fallbackSlideSize={fallbackSlideSize}
    />
  );

  if (!isClient) return fallback;

  return (
    <FileErrorBoundary
      key={descriptorKey}
      descriptor={descriptor}
      resource={resource}
      className={className}
      resetKey={descriptorKey}
      showDownload={controls}
    >
      <React.Suspense fallback={fallback}>
        <FileViewerRoute
          className={className}
          controls={controls}
          descriptor={descriptor}
          descriptorSignal={descriptorSignal}
          fallbackFrameSize={fallbackFrameSize}
          fallbackSlideSize={fallbackSlideSize}
          frame="none"
          isolateStyles={isolateStyles}
          resource={resource}
        />
      </React.Suspense>
    </FileErrorBoundary>
  );
}

"use client";

import type {
  FileViewerDocumentSurface,
  FileViewerMotionKernel,
} from "./file-viewer-motion-kernel";

export const FILE_VIEWER_BEFORE_LAYOUT_MOTION_EVENT =
  "file-viewer:before-layout-motion";

export type FileViewerElements = {
  documentSurfaceElement: HTMLElement | null;
  sidebarElement: HTMLElement | null;
  sidebarGapElement: HTMLDivElement | null;
  sidebarTriggerElement: HTMLElement | null;
  viewerShellElement: HTMLDivElement | null;
};

export type FileViewerElementRegistry = {
  getElements: () => FileViewerElements;
  registerDocumentSurface: (surface: FileViewerDocumentSurface) => () => void;
  registerSidebarElement: (element: HTMLElement | null) => void;
  registerSidebarGapElement: (element: HTMLDivElement | null) => void;
  registerSidebarTriggerElement: (element: HTMLElement | null) => void;
  registerViewerShellElement: (element: HTMLDivElement | null) => void;
};

export function createFileViewerElementRegistry({
  motionKernel,
  onViewerShellElementChange,
}: {
  motionKernel: FileViewerMotionKernel;
  onViewerShellElementChange: (element: HTMLDivElement | null) => void;
}): FileViewerElementRegistry {
  const elements: FileViewerElements = {
    documentSurfaceElement: null,
    sidebarElement: null,
    sidebarGapElement: null,
    sidebarTriggerElement: null,
    viewerShellElement: null,
  };
  let documentSurfaceRegistration = 0;

  return {
    getElements: () => elements,
    registerDocumentSurface: (surface) => {
      documentSurfaceRegistration += 1;
      const registration = documentSurfaceRegistration;
      elements.documentSurfaceElement = surface.element;
      motionKernel.setDocumentSurface(surface);
      return () => {
        if (documentSurfaceRegistration !== registration) return;
        elements.documentSurfaceElement = null;
        motionKernel.setDocumentSurface(null);
      };
    },
    registerSidebarElement: (element) => {
      if (elements.sidebarElement === element) return;
      elements.sidebarElement = element;
    },
    registerSidebarGapElement: (element) => {
      if (elements.sidebarGapElement === element) return;
      elements.sidebarGapElement = element;
      motionKernel.setSidebarGapElement(element);
    },
    registerSidebarTriggerElement: (element) => {
      elements.sidebarTriggerElement = element;
    },
    registerViewerShellElement: (element) => {
      if (elements.viewerShellElement === element) return;
      elements.viewerShellElement = element;
      onViewerShellElementChange(element);
    },
  };
}

"use client";

import * as React from "react";

import {
  fileViewerDiagnostic,
  summarizeViewerDescriptor,
  summarizeViewerError,
  summarizeViewerResource,
} from "@/lib/pdf-viewer-diagnostics";
import { cn } from "@/lib/utils";
import type { ViewerResource } from "@/lib/viewer-resource";
import { Skeleton } from "@/components/ui/skeleton";

import { CodeViewerFallback } from "./code-viewer-chrome";
import { DocxViewerFallback } from "./docx-viewer-chrome";
import {
  isProseTextDescriptor,
  type FileDescriptor,
  type FileViewerFallbackSize,
} from "./file-viewer-core";
import {
  FileViewerErrorState,
  FileViewerLoadingState,
  FileViewerUnsupportedState,
} from "./file-viewer-state";
import { ImageViewerFallback } from "./image-viewer-chrome";
import { PdfViewerFallback } from "./pdf-viewer-states";
import { PptxViewerFallback } from "./pptx-viewer-fallback";
import { TextViewerFallback } from "./text-viewer-chrome";
import { ViewerControlsSkeleton } from "./viewer-controls";
import { XlsxViewerFallback } from "./xlsx-viewer-chrome";

export function UnsupportedCard({
  resource,
  className,
  bare,
  message,
  showDownload = true,
}: {
  resource: ViewerResource;
  className?: string;
  bare?: boolean;
  message?: string;
  showDownload?: boolean;
}) {
  return (
    <FileViewerUnsupportedState
      className={cn(
        bare ? "bg-muted/20 h-full" : "bg-muted/30 min-h-64 rounded-xl border",
        className,
      )}
      description={
        message ?? `No preview is available for ${resource.fileName}.`
      }
      download={resource.originalDownload}
      fileName={resource.fileName}
      showDownload={showDownload}
    />
  );
}

export function ViewerFallback({
  resource,
  className,
  bare = false,
  controls = true,
  fallbackFrameSize,
  fallbackSlideSize,
}: {
  resource: ViewerResource;
  className?: string;
  bare?: boolean;
  controls?: boolean;
  fallbackFrameSize?: FileViewerFallbackSize;
  fallbackSlideSize?: FileViewerFallbackSize;
}) {
  const descriptor = resource.descriptor;
  const category = descriptor.category;

  // Render the exact per-type skeleton each viewer shows while it parses, so the
  // SSR + chunk-loading paint is identical to the in-viewer loading state (same
  // controls row, same body) — no controls popping in and no geometry shift as one
  // skeleton hands off to the next.
  switch (category) {
    case "pdf":
      return (
        <PdfViewerFallback
          bare={bare}
          className={className}
          controls={controls}
        />
      );
    case "docx":
      return (
        <DocxViewerFallback
          bare={bare}
          className={className}
          controls={controls}
        />
      );
    case "pptx":
      return (
        <PptxViewerFallback
          bare={bare}
          className={className}
          controls={controls}
          fallbackSlideSize={fallbackSlideSize}
        />
      );
    case "image":
      return (
        <ImageViewerFallback
          bare={bare}
          className={className}
          controls={controls}
          fallbackFrameSize={fallbackFrameSize}
        />
      );
    case "xlsx":
      return (
        <XlsxViewerFallback
          bare={bare}
          className={className}
          controls={controls}
        />
      );
    case "markdown":
      return (
        <TextViewerFallback
          bare={bare}
          className={className}
          controls={controls}
        />
      );
    case "text":
      // The "text" category fans out to a prose viewer or a code viewer; match
      // whichever the route will pick so the body skeleton (gutter vs none) lines up.
      return isProseTextDescriptor(descriptor) ? (
        <TextViewerFallback
          bare={bare}
          className={className}
          controls={controls}
        />
      ) : (
        <CodeViewerFallback
          bare={bare}
          className={className}
          controls={controls}
        />
      );
    case "csv":
      return (
        <TextFamilyFallbackFrame bare={bare} className={className}>
          {controls ? (
            <ViewerControlsSkeleton title subtitle zoom download />
          ) : null}
          <TableBodySkeleton />
        </TextFamilyFallbackFrame>
      );
    case "html":
      return (
        <TextFamilyFallbackFrame bare={bare} className={className}>
          {controls ? <ViewerControlsSkeleton zoom /> : null}
          <div className="bg-card min-h-0 flex-1 p-4">
            <Skeleton className="size-full rounded-md" />
          </div>
        </TextFamilyFallbackFrame>
      );
  }

  // Unsupported / unknown categories: a neutral page-sheet placeholder.
  return (
    <FileViewerLoadingState
      description={null}
      icon={null}
      title={null}
      className={cn(
        "flex min-h-0 flex-col items-stretch justify-start gap-0 overflow-hidden p-0 text-left",
        bare ? "bg-muted/20 h-full" : "bg-muted/20 min-h-64",
        className,
      )}
    >
      <div
        data-slot="file-viewer-document-fallback"
        className="min-h-0 flex-1 overflow-hidden"
      >
        <div className="flex flex-col items-center p-4">
          <Skeleton
            aria-hidden
            className="ring-border w-full rounded-none shadow-sm ring-1"
            style={{ aspectRatio: "8.5 / 11" }}
          />
        </div>
      </div>
    </FileViewerLoadingState>
  );
}

function TextFamilyFallbackFrame({
  bare,
  className,
  children,
}: {
  bare?: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <div
      data-slot="file-viewer-document-fallback"
      className={cn(
        "bg-card flex min-h-0 flex-1 flex-col overflow-hidden",
        bare ? "h-full" : "min-h-64",
        className,
      )}
    >
      {children}
    </div>
  );
}

function TableBodySkeleton() {
  const gutter = 52;
  const colWidth = 150;
  const cols = 6;
  const rows = 14;
  const widths = [70, 45, 88, 56, 62, 78];
  return (
    <div
      aria-hidden
      className="bg-card flex min-h-0 flex-1 flex-col overflow-hidden text-sm"
    >
      <div className="bg-muted/60 flex border-b">
        <div
          className="shrink-0 border-r"
          style={{ width: gutter, height: 33 }}
        />
        {Array.from({ length: cols }, (_, c) => (
          <div
            key={c}
            className="flex shrink-0 items-center border-r px-3"
            style={{ width: colWidth, height: 33 }}
          >
            <Skeleton className="h-3 w-16" />
          </div>
        ))}
      </div>
      <div className="min-h-0 flex-1 overflow-hidden">
        {Array.from({ length: rows }, (_, r) => (
          <div key={r} className="flex border-b" style={{ height: 33 }}>
            <div
              className="flex shrink-0 items-center justify-end border-r px-2"
              style={{ width: gutter }}
            >
              <Skeleton className="h-3 w-4" />
            </div>
            {Array.from({ length: cols }, (_, c) => (
              <div
                key={c}
                className="flex shrink-0 items-center border-r px-3"
                style={{ width: colWidth }}
              >
                <Skeleton
                  className="h-3"
                  style={{ width: `${widths[(r + c) % widths.length]}%` }}
                />
              </div>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}

export class FileErrorBoundary extends React.Component<
  {
    children: React.ReactNode;
    descriptor: FileDescriptor;
    resource: ViewerResource;
    className?: string;
    resetKey?: unknown;
    showDownload?: boolean;
  },
  { error: unknown | null }
> {
  state: Readonly<{ error: unknown | null }> = { error: null };

  componentDidUpdate(prev: { resetKey?: unknown }) {
    if (prev.resetKey !== this.props.resetKey && this.state.error) {
      fileViewerDiagnostic("debug", "file_viewer_error_boundary_reset", {
        descriptor: summarizeViewerDescriptor(this.props.descriptor),
        resource: summarizeViewerResource(this.props.resource),
      });
      this.setState({ error: null });
    }
  }

  static getDerivedStateFromError(error: unknown) {
    return { error };
  }

  componentDidCatch(error: unknown) {
    fileViewerDiagnostic("error", "file_viewer_error_boundary_caught", {
      descriptor: summarizeViewerDescriptor(this.props.descriptor),
      resource: summarizeViewerResource(this.props.resource),
      error: summarizeViewerError(error),
    });
  }

  render() {
    if (this.state.error != null) {
      return (
        <FileViewerErrorState
          error={this.state.error}
          format="file"
          sourceKind={this.props.resource.sourceKind}
          download={
            this.props.showDownload === false
              ? null
              : this.props.resource.originalDownload
          }
          className={this.props.className}
        />
      );
    }
    return this.props.children;
  }
}

