    </FileViewerShellStaticContext.Provider>
  );
}

"use client";

import * as React from "react";

import { restoreFileViewerSidebarFocusOnClose } from "./file-viewer-accessibility";
import {
  useFileViewerContext,
  type FileViewerContextValue,
  type FileViewerSetSidebarRequestedOpen,
  type FileViewerShellStaticContextValue,
  type FileViewerSidebarCollapsible,
  type FileViewerSidebarDynamicContextValue,
  type FileViewerSidebarMode,
  type FileViewerSidebarRequestedMode,
  type FileViewerSidebarSide,
  type FileViewerSidebarState,
} from "./file-viewer-context";
import { createFileViewerElementRegistry } from "./file-viewer-elements";
import { useFileViewerFrameKeyboard } from "./file-viewer-frame-keyboard";
import {
  createFileViewerMotionKernel,
  useFileViewerMotionFrame,
} from "./file-viewer-motion-kernel";
import type { FileViewerMotionTarget } from "./file-viewer-motion-plan";
import { useFileViewerSidebarOpenController } from "./file-viewer-sidebar-open-state";
import { useFileViewerSidebarRegistration } from "./file-viewer-sidebar-registration";
import {
  readElementRectSnapshot,
  useStableElementSize,
} from "./viewer-measurement";

export const FILE_VIEWER_INLINE_BREAKPOINT = 768;

const FILE_VIEWER_MOTION_DURATION_MS = 150;

type FileViewerFrameControllerOptions = {
  inlineBreakpoint: number;
  sidebarMode: FileViewerSidebarRequestedMode;
};

export type FileViewerFrameController = {
  effectiveCollapsible: FileViewerSidebarCollapsible;
  headerMode: FileViewerContextValue["headerMode"];
  isSidebarRequestedOpen: boolean;
  mode: FileViewerSidebarMode;
  resourceCategory: FileViewerContextValue["resourceCategory"];
  rootId: string;
  setRootElement: (element: HTMLDivElement | null) => void;
  shellStaticContext: FileViewerShellStaticContextValue;
  side: FileViewerSidebarSide;
  sidebarDynamicContext: FileViewerSidebarDynamicContextValue;
  sidebarState: FileViewerSidebarState;
};

export function useFileViewerFrameController({
  inlineBreakpoint,
  sidebarMode,
}: FileViewerFrameControllerOptions): FileViewerFrameController {
  const context = useFileViewerContext();

  if (!context.isInsideFileViewer) {
    throw new Error("FileViewer must be rendered within FileViewerProvider.");
  }

  const rootId = React.useId();
  const fallbackSidebarId = `${rootId}-sidebar`;
  // The kernel owns time + style writes only; its settle-hold layout reads are
  // injected from the quarantined measurement module here at the controller
  // layer.
  const motionKernel = React.useMemo(
    () => createFileViewerMotionKernel({ readElementRectSnapshot }),
    [],
  );
  const size = useStableElementSize<HTMLDivElement>({
    retainLastNonZero: true,
  });
  const elementRegistry = React.useMemo(
    () =>
      createFileViewerElementRegistry({
        motionKernel,
        onViewerShellElementChange: size.setElement,
      }),
    [motionKernel, size.setElement],
  );
  const {
    canToggleSidebar,
    effectiveCollapsible,
    registerSidebar,
    side,
    sidebarId,
    sidebarWidth,
    sidebarWidthPixels,
  } = useFileViewerSidebarRegistration({
    fallbackSidebarId,
  });
  const openController = useFileViewerSidebarOpenController({
    ...context.sidebarOpenProps,
    collapsible: effectiveCollapsible,
  });
  const isSidebarRequestedOpen = openController.isSidebarRequestedOpen;
  const motionFrame = useFileViewerMotionFrame(motionKernel);
  const isSidebarTransitioning = motionFrame.phase === "sliding";
  const mode = resolveFileViewerSidebarMode({
    inlineBreakpoint,
    requestedMode: sidebarMode,
    width: size.width,
  });
  const isSidebarInteractive = resolveFileViewerSidebarInteractive({
    canToggleSidebar,
    collapsible: effectiveCollapsible,
    isSidebarRequestedOpen,
    isSidebarTransitioning,
    mode,
  });
  const sidebarState: FileViewerSidebarState = isSidebarRequestedOpen
    ? "expanded"
    : "collapsed";
  const motionTarget = React.useMemo<FileViewerMotionTarget>(
    () => ({
      shellInlineSize: size.width ?? 0,
      durationMs: FILE_VIEWER_MOTION_DURATION_MS,
      mode,
      open: isSidebarRequestedOpen,
      side,
      sidebarWidth: sidebarWidthPixels,
    }),
    [isSidebarRequestedOpen, mode, side, sidebarWidthPixels, size.width],
  );
  const motionTargetRef = React.useRef(motionTarget);

  const setRootElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      elementRegistry.registerViewerShellElement(element);
    },
    [elementRegistry],
  );

  React.useLayoutEffect(() => {
    motionTargetRef.current = motionTarget;
  }, [motionTarget]);

  // Adopt idle geometry (mount, resizes, mode flips) without animating. While
  // a motion is in flight the kernel owns the target; it re-syncs here once
  // the contract returns to idle.
  React.useLayoutEffect(() => {
    if (motionFrame.phase !== "idle") return;
    motionKernel.syncTarget(motionTarget);
  }, [motionFrame.phase, motionKernel, motionTarget]);

  // Single owner of focus restoration: when the sidebar stops being
  // interactive while focus is inside it, hand focus back to the trigger.
  const previousIsSidebarInteractiveRef = React.useRef(isSidebarInteractive);
  React.useLayoutEffect(() => {
    restoreFileViewerSidebarFocusOnClose({
      elements: elementRegistry.getElements(),
      isSidebarInteractive,
      previousIsSidebarInteractive: previousIsSidebarInteractiveRef.current,
    });
    previousIsSidebarInteractiveRef.current = isSidebarInteractive;
  }, [elementRegistry, isSidebarInteractive]);

  const setSidebarRequestedOpen =
    React.useCallback<FileViewerSetSidebarRequestedOpen>(
      (value) => {
        // Toggling requires a registered, collapsible sidebar; a non-collapsible
        // sidebar is pinned open and an unregistered one has nothing to move.
        if (!canToggleSidebar) return;

        const currentOpen = openController.getSidebarRequestedOpen();
        const nextOpen = typeof value === "function" ? value(currentOpen) : value;
        if (nextOpen === currentOpen) return;

        openController.setSidebarRequestedOpen(nextOpen);
        const nextTarget: FileViewerMotionTarget = {
          ...motionTargetRef.current,
          open: nextOpen,
        };
        motionTargetRef.current = nextTarget;
        motionKernel.startMotion(nextTarget);
      },
      [canToggleSidebar, motionKernel, openController],
    );
  const toggleSidebarRequestedOpen = React.useCallback(
    () => setSidebarRequestedOpen((open) => !open),
    [setSidebarRequestedOpen],
  );
  const closeSidebar = React.useCallback(
    () => setSidebarRequestedOpen(false),
    [setSidebarRequestedOpen],
  );

  useFileViewerFrameKeyboard({
    canToggleSidebar,
    closeSidebar,
    elementRegistry,
    isSidebarInteractive,
    viewerShellElement: size.element,
  });

  const shellStaticContext = React.useMemo<FileViewerShellStaticContextValue>(
    () => ({
      canToggleSidebar,
      collapsible: effectiveCollapsible,
      elementRegistry,
      mode,
      motionDurationMs: FILE_VIEWER_MOTION_DURATION_MS,
      motionKernel,
      registerSidebar,
      rootId,
      setSidebarRequestedOpen,
      side,
      sidebarId,
      sidebarWidth,
      toggleSidebarRequestedOpen,
    }),
    [
      canToggleSidebar,
      effectiveCollapsible,
      elementRegistry,
      mode,
      motionKernel,
      registerSidebar,
      rootId,
      setSidebarRequestedOpen,
      side,
      sidebarId,
      sidebarWidth,
      toggleSidebarRequestedOpen,
    ],
  );
  const sidebarDynamicContext =
    React.useMemo<FileViewerSidebarDynamicContextValue>(
      () => ({
        isSidebarInteractive,
        isSidebarRequestedOpen,
        isSidebarTransitioning,
        sidebarState,
      }),
      [
        isSidebarInteractive,
        isSidebarRequestedOpen,
        isSidebarTransitioning,
        sidebarState,
      ],
    );

  return {
    effectiveCollapsible,
    headerMode: context.headerMode,
    isSidebarRequestedOpen,
    mode,
    resourceCategory: context.resourceCategory,
    rootId,
    setRootElement,
    shellStaticContext,
    side,
    sidebarDynamicContext,
    sidebarState,
  };
}

// An inline sidebar stays non-interactive while its geometry is in motion:
// closing makes it inert immediately, opening keeps it inert until the
// settle publish leaves the "sliding" phase.
function resolveFileViewerSidebarInteractive({
  canToggleSidebar,
  collapsible,
  isSidebarRequestedOpen,
  isSidebarTransitioning,
  mode,
}: {
  canToggleSidebar: boolean;
  collapsible: FileViewerSidebarCollapsible;
  isSidebarRequestedOpen: boolean;
  isSidebarTransitioning: boolean;
  mode: FileViewerSidebarMode;
}): boolean {
  if (collapsible === "none") return true;
  if (!isSidebarRequestedOpen) return false;
  return !(mode === "inline" && canToggleSidebar && isSidebarTransitioning);
}

function resolveFileViewerSidebarMode({
  inlineBreakpoint,
  requestedMode,
  width,
}: {
  inlineBreakpoint: number;
  requestedMode: FileViewerSidebarRequestedMode;
  width: number | null;
}): FileViewerSidebarMode {
  if (requestedMode !== "auto") return requestedMode;
  if (width === null) return "overlay";
  return width >= inlineBreakpoint ? "inline" : "overlay";
}

"use client";

import * as React from "react";

import type { FileViewerElementRegistry } from "./file-viewer-elements";
import {
  isFileViewerActiveElementInsideShell,
  shouldCloseFileViewerSidebarOnEscape,
} from "./file-viewer-keyboard";

export function useFileViewerFrameKeyboard({
  canToggleSidebar,
  closeSidebar,
  elementRegistry,
  isSidebarInteractive,
  viewerShellElement,
}: {
  canToggleSidebar: boolean;
  closeSidebar: () => void;
  elementRegistry: FileViewerElementRegistry;
  isSidebarInteractive: boolean;
  viewerShellElement: HTMLDivElement | null;
}) {
  React.useLayoutEffect(() => {
    const ownerDocument = viewerShellElement?.ownerDocument;
    if (!ownerDocument) return;

    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        !shouldCloseFileViewerSidebarOnEscape({
          canToggleSidebar,
          event,
          isSidebarInteractive,
        })
      ) {
        return;
      }

      if (
        !isFileViewerActiveElementInsideShell({
          activeElement: ownerDocument.activeElement,
          viewerShellElement: elementRegistry.getElements().viewerShellElement,
        })
      ) {
        return;
      }

      event.preventDefault();
      closeSidebar();
    };

    ownerDocument.addEventListener("keydown", handleKeyDown);
    return () => ownerDocument.removeEventListener("keydown", handleKeyDown);
  }, [
    canToggleSidebar,
    closeSidebar,
    elementRegistry,
    isSidebarInteractive,
    viewerShellElement,
  ]);
}

"use client";

import * as React from "react";

import { resolveFileViewerSidebarAccessibilityProps } from "./file-viewer-accessibility";
import {
  type FileViewerSidebarCollapsible,
  type FileViewerSidebarMode,
  type FileViewerSidebarSide,
  type FileViewerSidebarState,
  useFileViewerShell,
} from "./file-viewer-context";
import { useIsInsideFileViewerContent } from "./file-viewer-layout";
import { useStableCssLength, useStableElementSize } from "./viewer-measurement";

export type FileViewerSidebarController = {
  accessibilityProps: ReturnType<
    typeof resolveFileViewerSidebarAccessibilityProps
  >;
  customProperties: React.CSSProperties;
  isInline: boolean;
  isSidebarRequestedOpen: boolean;
  mode: FileViewerSidebarMode;
  panelStyle: React.CSSProperties;
  resolvedCollapsible: FileViewerSidebarCollapsible;
  resolvedSide: FileViewerSidebarSide;
  setSidebarGapElement: (element: HTMLDivElement | null) => void;
  setSidebarPanelElement: (element: HTMLElement | null) => void;
  sidebarId: string;
  sidebarState: FileViewerSidebarState;
};

export function useFileViewerSidebarController({
  collapsible,
  id,
  side,
  style,
  width,
}: {
  collapsible: FileViewerSidebarCollapsible | undefined;
  id: string | undefined;
  side: FileViewerSidebarSide | undefined;
  style: React.CSSProperties | undefined;
  width: string;
}): FileViewerSidebarController {
  const isInsideContent = useIsInsideFileViewerContent();
  const shell = useFileViewerShell("FileViewerSidebar");
  const registerSidebar = shell.registerSidebar;
  const sidebarSize = useStableElementSize<HTMLElement>({
    observe: false,
    retainLastNonZero: true,
  });
  const reactId = React.useId();
  const sidebarId = id ?? `${reactId}-file-viewer-sidebar`;
  const resolvedCollapsible = collapsible ?? shell.collapsible;
  const resolvedSide = side ?? shell.side;
  const isSidebarRequestedOpen =
    resolvedCollapsible === "none" ? true : shell.isSidebarRequestedOpen;
  const isSidebarInteractive =
    resolvedCollapsible === "none" ? true : shell.isSidebarInteractive;
  const sidebarState = isSidebarRequestedOpen ? "expanded" : "collapsed";
  const isInline = shell.mode === "inline";
  const declaredWidthPixels = useStableCssLength({
    element: sidebarSize.element,
    value: width,
  });
  const widthPixels =
    declaredWidthPixels > 0 ? declaredWidthPixels : (sidebarSize.width ?? 0);
  const setSidebarGapElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      shell.elementRegistry.registerSidebarGapElement(element);
    },
    [shell.elementRegistry],
  );
  const setSidebarPanelElement = React.useCallback(
    (element: HTMLElement | null) => {
      sidebarSize.setElement(element);
      shell.elementRegistry.registerSidebarElement(element);
    },
    [shell.elementRegistry, sidebarSize.setElement],
  );

  if (process.env.NODE_ENV !== "production" && !isInsideContent) {
    throw new Error(
      "FileViewerSidebar must be rendered inside FileViewerContent.",
    );
  }

  React.useLayoutEffect(
    () =>
      registerSidebar({
        collapsible: resolvedCollapsible,
        id: sidebarId,
        side: resolvedSide,
        width,
        widthPixels,
      }),
    [
      registerSidebar,
      resolvedCollapsible,
      resolvedSide,
      sidebarId,
      width,
      widthPixels,
    ],
  );

  const accessibilityProps = resolveFileViewerSidebarAccessibilityProps({
    collapsible: resolvedCollapsible,
    deferInert:
      !isSidebarRequestedOpen &&
      !isSidebarInteractive &&
      shell.isSidebarTransitioning,
    isSidebarInteractive,
  });
  const customProperties = pickCssCustomProperties(style);
  const panelStyle: React.CSSProperties = {
    width,
    ...style,
    ...(isSidebarInteractive ? null : { pointerEvents: "none" as const }),
  };

  // No memo: `panelStyle` and `customProperties` are fresh objects every
  // render, so the controller value can never be referentially stable anyway.
  return {
    accessibilityProps,
    customProperties,
    isInline,
    isSidebarRequestedOpen,
    mode: shell.mode,
    panelStyle,
    resolvedCollapsible,
    resolvedSide,
    setSidebarGapElement,
    setSidebarPanelElement,
    sidebarId,
    sidebarState,
  };
}

function pickCssCustomProperties(style: React.CSSProperties | undefined) {
  if (!style) return {};

  return Object.fromEntries(
    Object.entries(style).filter(([name]) => name.startsWith("--")),
  ) as React.CSSProperties;
}

"use client";

import * as React from "react";

import type {
  FileViewerSidebarCollapsible,
  FileViewerSidebarOpenProps,
} from "./file-viewer-context";

export type FileViewerSidebarOpenController = {
  getSidebarRequestedOpen: () => boolean;
  isSidebarRequestedOpen: boolean;
  setSidebarRequestedOpen: (isSidebarRequestedOpen: boolean) => void;
};

// Bridges the controlled/uncontrolled `open` prop pair to real React state, so
// every toggle re-renders the tree and the declarative writers (data
// attributes, inert/aria, overlay translate classes) stay current.
export function useFileViewerSidebarOpenController({
  collapsible,
  defaultOpen,
  onOpenChange,
  open,
}: FileViewerSidebarOpenProps & {
  collapsible: FileViewerSidebarCollapsible;
}): FileViewerSidebarOpenController {
  const isControlled = open !== undefined;
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(
    defaultOpen ?? false,
  );
  const isSidebarRequestedOpen =
    collapsible === "none" ? true : (open ?? uncontrolledOpen);
  const openRef = React.useRef(isSidebarRequestedOpen);

  React.useLayoutEffect(() => {
    openRef.current = isSidebarRequestedOpen;
  }, [isSidebarRequestedOpen]);

  const getSidebarRequestedOpen = React.useCallback(() => openRef.current, []);

  const setSidebarRequestedOpen = React.useCallback(
    (nextIsSidebarRequestedOpen: boolean) => {
      openRef.current = nextIsSidebarRequestedOpen;
      if (!isControlled) {
        setUncontrolledOpen(nextIsSidebarRequestedOpen);
      }
      onOpenChange?.(nextIsSidebarRequestedOpen);
    },
    [isControlled, onOpenChange],
  );

  return React.useMemo(
    () => ({
      getSidebarRequestedOpen,
      isSidebarRequestedOpen,
      setSidebarRequestedOpen,
    }),
    [getSidebarRequestedOpen, isSidebarRequestedOpen, setSidebarRequestedOpen],
  );
}

"use client";

import * as React from "react";

import {
  DEFAULT_FILE_VIEWER_SIDEBAR_WIDTH,
  type FileViewerSidebarCollapsible,
  type FileViewerSidebarRegistration,
  type FileViewerSidebarSide,
} from "./file-viewer-context";

export type FileViewerSidebarRegistrationController = {
  canToggleSidebar: boolean;
  effectiveCollapsible: FileViewerSidebarCollapsible;
  registerSidebar: (registration: FileViewerSidebarRegistration) => () => void;
  side: FileViewerSidebarSide;
  sidebarId: string;
  sidebarWidth: string;
  sidebarWidthPixels: number;
};

// The mounted FileViewerSidebar is the single source of sidebar configuration
// (collapsible, side, width); the shell only holds neutral defaults until one
// registers. No sidebar registered means nothing to toggle and no motion, so
// no fallback width measurement is needed.
export function useFileViewerSidebarRegistration({
  fallbackSidebarId,
}: {
  fallbackSidebarId: string;
}): FileViewerSidebarRegistrationController {
  const [sidebarRegistration, setSidebarRegistration] =
    React.useState<FileViewerSidebarRegistration | null>(null);
  const effectiveCollapsible = sidebarRegistration?.collapsible ?? "offcanvas";
  const side = sidebarRegistration?.side ?? "left";
  const sidebarId = sidebarRegistration?.id ?? fallbackSidebarId;
  const sidebarWidth =
    sidebarRegistration?.width ?? DEFAULT_FILE_VIEWER_SIDEBAR_WIDTH;
  const sidebarWidthPixels = sidebarRegistration?.widthPixels ?? 0;
  const canToggleSidebar =
    sidebarRegistration !== null && effectiveCollapsible !== "none";

  const registerSidebar = React.useCallback(
    (registration: FileViewerSidebarRegistration) => {
      setSidebarRegistration(registration);
      return () => {
        setSidebarRegistration((current) =>
          current?.id === registration.id ? null : current,
        );
      };
    },
    [],
  );

  return React.useMemo(
    () => ({
      canToggleSidebar,
      effectiveCollapsible,
      registerSidebar,
      side,
      sidebarId,
      sidebarWidth,
      sidebarWidthPixels,
    }),
    [
      canToggleSidebar,
      effectiveCollapsible,
      registerSidebar,
      side,
      sidebarId,
      sidebarWidth,
      sidebarWidthPixels,
    ],
  );
}

"use client";

import * as React from "react";
import { flushSync } from "react-dom";

import { FILE_VIEWER_BEFORE_LAYOUT_MOTION_EVENT } from "./file-viewer-elements";
import {
  areFileViewerMotionFramesEqual,
  areFileViewerMotionRestFramesEqual,
  createFileViewerIdleMotionFrame,
  createFileViewerMotionPlan,
  createFileViewerMotionRestFrame,
  type FileViewerMotionFrame,
  type FileViewerMotionPlan,
  type FileViewerMotionRestFrame,
  type FileViewerMotionTarget,
} from "./file-viewer-motion-plan";

// The kernel is the single owner of sidebar motion. It holds the clock (one
// rAF loop from slide start through settle), writes the continuous inline
// styles, and publishes to React subscribers only at phase edges
// (idle → sliding → settling → idle). Everything discrete — data attributes,
// inert/aria, the overlay translate classes — is owned by React renders.
export type FileViewerMotionKernel = {
  getInteractiveSnapshot: () => FileViewerMotionFrame;
  getSnapshot: () => FileViewerMotionFrame;
  setDocumentSurface: (surface: FileViewerDocumentSurface | null) => void;
  setSidebarGapElement: (element: HTMLElement | null) => void;
  startMotion: (target: FileViewerMotionTarget) => void;
  subscribe: (listener: () => void) => () => void;
  syncTarget: (target: FileViewerMotionTarget) => void;
};

export type FileViewerDocumentSurface = {
  element: HTMLElement;
  readSettleSnapshot?: FileViewerDocumentSurfaceSettleSnapshotReader | null;
  resolveMotionStyle?: FileViewerDocumentSurfaceMotionResolver | null;
};

export type FileViewerDocumentSurfaceSettleSnapshotReader = () =>
  | readonly number[]
  | null
  | undefined;

// Layout reads are quarantined outside the kernel (viewer-measurement / the
// frame controller layer). The kernel owns time and style writes only, so the
// settle-hold rect reader is injected by its creator rather than imported.
export type FileViewerElementRectSnapshotReader = (
  element: HTMLElement | null,
) => readonly number[];

export type FileViewerMotionKernelOptions = {
  readElementRectSnapshot?: FileViewerElementRectSnapshotReader | null;
};

export type FileViewerDocumentSurfaceMotionStyle = {
  customProperties?: Readonly<Record<string, string | null>>;
  transform: string;
  transformOrigin: string;
  willChange: string;
};

export type FileViewerDocumentSurfaceMotionResolver = (
  frame: FileViewerMotionFrame,
) => FileViewerDocumentSurfaceMotionStyle | null;

type FileViewerActiveMotion = {
  durationMs: number;
  from: FileViewerMotionRestFrame;
  id: number;
  startedAt: number;
  to: FileViewerMotionRestFrame;
};

type FileViewerSettleRelease = {
  idleFrame: FileViewerMotionFrame;
  lastSnapshot: readonly number[];
  remainingFrameCount: number;
  settlingFrame: FileViewerMotionFrame;
  stableFrameCount: number;
};

const FILE_VIEWER_SETTLE_SCROLL_EPSILON_PX = 0.25;
const FILE_VIEWER_SETTLE_STABLE_FRAME_COUNT = 2;
const FILE_VIEWER_SETTLE_MAX_HOLD_FRAMES = 6;
const FILE_VIEWER_SUBPIXEL_ENDPOINT_EPSILON_PX = 1;

export const DEFAULT_FILE_VIEWER_MOTION_FRAME: FileViewerMotionFrame = {
  shellInlineSize: 0,
  durationMs: 150,
  fallbackSurfaceScale: 1,
  fromInlineSize: 0,
  layoutInlineSize: 0,
  mode: "overlay",
  motionId: null,
  motionProgress: 1,
  open: false,
  phase: "idle",
  side: "left",
  sidebarInlineSize: 0,
  sidebarWidth: 0,
  toInlineSize: 0,
};

export function createFileViewerMotionKernel({
  readElementRectSnapshot = null,
}: FileViewerMotionKernelOptions = {}): FileViewerMotionKernel {
  const listeners = new Set<() => void>();
  let contractFrame = DEFAULT_FILE_VIEWER_MOTION_FRAME;
  let interactiveFrame = DEFAULT_FILE_VIEWER_MOTION_FRAME;
  let target: FileViewerMotionTarget = {
    shellInlineSize: 0,
    durationMs: DEFAULT_FILE_VIEWER_MOTION_FRAME.durationMs,
    mode: DEFAULT_FILE_VIEWER_MOTION_FRAME.mode,
    open: DEFAULT_FILE_VIEWER_MOTION_FRAME.open,
    side: DEFAULT_FILE_VIEWER_MOTION_FRAME.side,
    sidebarWidth: 0,
  };
  let documentSurface: FileViewerDocumentSurface | null = null;
  let documentSurfaceCustomProperties = new Set<string>();
  let sidebarGapElement: HTMLElement | null = null;
  let activeMotion: FileViewerActiveMotion | null = null;
  let settleRelease: FileViewerSettleRelease | null = null;
  let rafHandle = 0;
  let settleReleaseHandle = 0;
  let motionSequence = 0;

  const notify = () => {
    for (const listener of listeners) listener();
  };

  const publishContractFrame = (
    nextFrame: FileViewerMotionFrame,
    { flushSubscribers = false }: { flushSubscribers?: boolean } = {},
  ) => {
    if (areFileViewerMotionFramesEqual(contractFrame, nextFrame)) return;
    contractFrame = nextFrame;

    if (flushSubscribers) {
      flushSync(notify);
      return;
    }

    notify();
  };

  // The gap's inline size and the document surface's counter-scale must land
  // in the same frame: two independent CSS transitions (width on the gap,
  // transform on the surface) can desync under main-thread jank, letting the
  // document edge drift off the sidebar edge mid-slide. The kernel therefore
  // writes both here, once per tick.
  const writeElementStyles = (nextFrame: FileViewerMotionFrame) => {
    writeSidebarGapStyle(nextFrame);
    writeDocumentSurfaceStyle(nextFrame);
  };

  const commit = (
    nextFrame: FileViewerMotionFrame,
    { publish = true }: { publish?: boolean } = {},
  ) => {
    writeElementStyles(nextFrame);
    interactiveFrame = nextFrame;
    if (publish) publishContractFrame(nextFrame);
  };

  const cancelTick = () => {
    if (rafHandle === 0) return;
    getCancelAnimationFrame()(rafHandle);
    rafHandle = 0;
  };

  const cancelSettleRelease = () => {
    settleRelease = null;
    if (settleReleaseHandle === 0) return;
    getCancelAnimationFrame()(settleReleaseHandle);
    settleReleaseHandle = 0;
  };

  const readMotionSample = (
    motion: FileViewerActiveMotion,
    now = readNow(),
  ): FileViewerMotionFrame => {
    const rawMotionProgress =
      motion.durationMs <= 0
        ? 1
        : clamp((now - motion.startedAt) / motion.durationMs, 0, 1);
    const rawSidebarInlineSize = lerp(
      motion.from.sidebarInlineSize,
      motion.to.sidebarInlineSize,
      rawMotionProgress,
    );
    const isSubpixelEndpoint =
      rawMotionProgress > 0.98 &&
      Math.abs(rawSidebarInlineSize - motion.to.sidebarInlineSize) <=
        FILE_VIEWER_SUBPIXEL_ENDPOINT_EPSILON_PX;
    const motionProgress = isSubpixelEndpoint ? 1 : rawMotionProgress;
    const sidebarInlineSize = isSubpixelEndpoint
      ? motion.to.sidebarInlineSize
      : rawSidebarInlineSize;
    const layoutInlineSize = Math.max(
      0,
      motion.to.shellInlineSize - sidebarInlineSize,
    );
    const fromInlineSize = motion.from.layoutInlineSize;

    return {
      shellInlineSize: motion.to.shellInlineSize,
      durationMs: motion.durationMs,
      fromInlineSize,
      layoutInlineSize,
      mode: motion.to.mode,
      motionId: motion.id,
      motionProgress,
      open: motion.to.open,
      phase: motionProgress < 1 ? "sliding" : "settling",
      side: motion.to.side,
      sidebarInlineSize,
      sidebarWidth: motion.to.sidebarWidth,
      toInlineSize: motion.to.layoutInlineSize,
      fallbackSurfaceScale:
        fromInlineSize > 0 ? layoutInlineSize / fromInlineSize : 1,
    };
  };

  const settle = () => {
    if (!activeMotion) return;
    const finishedMotion = activeMotion;
    activeMotion = null;
    cancelTick();

    const idleFrame = createFileViewerIdleMotionFrame(finishedMotion.to);
    const settlingFrame: FileViewerMotionFrame = {
      ...idleFrame,
      fromInlineSize: finishedMotion.from.layoutInlineSize,
      motionId: finishedMotion.id,
      phase: "settling",
    };

    // Clear the counter-scale and re-lay-out the document at its target width
    // in one synchronous pass, so scroll rebasing never paints against stale
    // geometry.
    commit(settlingFrame, { publish: false });
    publishContractFrame(settlingFrame, { flushSubscribers: true });
    scheduleSettleRelease(settlingFrame, idleFrame);
  };

  const tick = () => {
    rafHandle = 0;
    if (!activeMotion) return;
    const sample = readMotionSample(activeMotion);
    if (sample.motionProgress >= 1) {
      settle();
      return;
    }
    commit(sample, { publish: false });
    scheduleTick();
  };

  const scheduleTick = () => {
    if (rafHandle !== 0) return;
    rafHandle = getRequestAnimationFrame()(tick);
  };

  const scheduleSettleRelease = (
    settlingFrame: FileViewerMotionFrame,
    idleFrame: FileViewerMotionFrame,
  ) => {
    cancelSettleRelease();
    settleRelease = {
      idleFrame,
      lastSnapshot: readSettleSnapshot(),
      remainingFrameCount: FILE_VIEWER_SETTLE_MAX_HOLD_FRAMES,
      settlingFrame,
      stableFrameCount: 0,
    };
    scheduleSettleReleaseFrame();
  };

  const scheduleSettleReleaseFrame = () => {
    if (settleReleaseHandle !== 0) return;
    settleReleaseHandle = getRequestAnimationFrame()(holdSettleRelease);
  };

  const holdSettleRelease = () => {
    settleReleaseHandle = 0;
    if (!settleRelease) return;

    commit(settleRelease.settlingFrame, { publish: false });

    const snapshot = readSettleSnapshot();
    const stableFrameCount = areSettleSnapshotsEqual(
      settleRelease.lastSnapshot,
      snapshot,
    )
      ? settleRelease.stableFrameCount + 1
      : 0;
    const remainingFrameCount = settleRelease.remainingFrameCount - 1;

    if (
      stableFrameCount >= FILE_VIEWER_SETTLE_STABLE_FRAME_COUNT ||
      remainingFrameCount <= 0
    ) {
      const idleFrame = settleRelease.idleFrame;
      settleRelease = null;
      commit(idleFrame);
      return;
    }

    settleRelease = {
      ...settleRelease,
      lastSnapshot: snapshot,
      remainingFrameCount,
      stableFrameCount,
    };
    scheduleSettleReleaseFrame();
  };

  const dispatchBeforeLayoutMotion = () => {
    documentSurface?.element.dispatchEvent(
      new Event(FILE_VIEWER_BEFORE_LAYOUT_MOTION_EVENT),
    );
  };

  const retarget = (nextTarget: FileViewerMotionTarget, animate: boolean) => {
    cancelSettleRelease();
    const currentFrame = activeMotion
      ? readMotionSample(activeMotion)
      : interactiveFrame.shellInlineSize > 0
        ? interactiveFrame
        : createFileViewerIdleMotionFrame(
            createFileViewerMotionRestFrame(target),
          );
    const plan = createFileViewerMotionPlan({
      animate: animate && !prefersReducedMotion(),
      currentFrame,
      nextTarget,
    });
    if (shouldDispatchBeforeLayoutMotion(plan)) {
      dispatchBeforeLayoutMotion();
    }
    target = plan.resolvedTarget;

    if (!plan.shouldAnimate) {
      activeMotion = null;
      cancelTick();
      commit(createFileViewerIdleMotionFrame(plan.nextRestFrame));
      return;
    }

    motionSequence += 1;
    activeMotion = {
      durationMs: plan.resolvedTarget.durationMs,
      from: { ...plan.currentRestFrame, layoutInlineSize: plan.fromInlineSize },
      id: motionSequence,
      startedAt: readNow(),
      to: plan.nextRestFrame,
    };
    commit(readMotionSample(activeMotion, activeMotion.startedAt));
    scheduleTick();
  };

  const syncTarget = (nextTarget: FileViewerMotionTarget) => {
    const nextRestFrame = createFileViewerMotionRestFrame(nextTarget);

    if (activeMotion) {
      target = nextTarget;
      if (areFileViewerMotionRestFramesEqual(activeMotion.to, nextRestFrame)) {
        return;
      }
      retarget(nextTarget, true);
      return;
    }

    cancelSettleRelease();
    target = nextTarget;
    commit(createFileViewerIdleMotionFrame(nextRestFrame));
  };

  return {
    getInteractiveSnapshot: () =>
      activeMotion ? readMotionSample(activeMotion) : interactiveFrame,
    getSnapshot: () => contractFrame,
    setDocumentSurface: (surface) => {
      const previousSurface = documentSurface;
      if (
        previousSurface &&
        (!surface || previousSurface.element !== surface.element)
      ) {
        clearDocumentSurfaceStyle(previousSurface.element);
      }
      documentSurface = surface;
      writeDocumentSurfaceStyle(interactiveFrame);
    },
    setSidebarGapElement: (element) => {
      sidebarGapElement = element;
      writeSidebarGapStyle(interactiveFrame);
    },
    startMotion: (nextTarget) => retarget(nextTarget, true),
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    syncTarget,
  };

  function writeSidebarGapStyle(nextFrame: FileViewerMotionFrame) {
    if (!sidebarGapElement) return;

    // Overlay motion is CSS-owned; relinquish the gap so its `w-0` class is
    // the only writer outside inline mode.
    if (nextFrame.mode !== "inline") {
      sidebarGapElement.style.width = "";
      sidebarGapElement.style.flexBasis = "";
      return;
    }

    sidebarGapElement.style.width = `${nextFrame.sidebarInlineSize}px`;
    sidebarGapElement.style.flexBasis = `${nextFrame.sidebarInlineSize}px`;
  }

  function writeDocumentSurfaceStyle(nextFrame: FileViewerMotionFrame) {
    if (!documentSurface) return;

    const { element, resolveMotionStyle } = documentSurface;
    const resolvedStyle = resolveMotionStyle?.(nextFrame);
    if (resolvedStyle) {
      writeDocumentSurfaceCustomProperties(
        element,
        resolvedStyle.customProperties,
      );
      element.style.transform = resolvedStyle.transform;
      element.style.transformOrigin = resolvedStyle.transformOrigin;
      element.style.willChange = resolvedStyle.willChange;
      return;
    }

    // Default (no motion resolver): identity. A surface that has no resolver is
    // one whose layout already tracks the live animating frame width (docx,
    // pptx, markdown) — it re-fits smoothly on its own, so applying the
    // `fallbackSurfaceScale` FLIP on top would double-count and overshoot the
    // target, then snap back at settle. Renderers whose content is a FIXED
    // raster that cannot re-fit live (PDF) register their own FLIP resolver.
    writeDocumentSurfaceCustomProperties(element, null);
    element.style.transform = "";
    element.style.transformOrigin = "";
    element.style.willChange = "";
  }

  function writeDocumentSurfaceCustomProperties(
    element: HTMLElement,
    customProperties:
      | Readonly<Record<string, string | null>>
      | null
      | undefined,
  ) {
    const nextNames = new Set(Object.keys(customProperties ?? {}));
    for (const name of documentSurfaceCustomProperties) {
      if (!nextNames.has(name)) {
        element.style.removeProperty(name);
      }
    }

    for (const [name, value] of Object.entries(customProperties ?? {})) {
      if (value == null) {
        element.style.removeProperty(name);
      } else {
        element.style.setProperty(name, value);
      }
    }

    documentSurfaceCustomProperties = nextNames;
  }

  function clearDocumentSurfaceStyle(element: HTMLElement) {
    element.style.transform = "";
    element.style.transformOrigin = "";
    element.style.willChange = "";
    for (const name of documentSurfaceCustomProperties) {
      element.style.removeProperty(name);
    }
    documentSurfaceCustomProperties = new Set();
  }

  function readSettleSnapshot(): readonly number[] {
    const values: number[] = [];

    appendElementRectSnapshot(values, sidebarGapElement);
    appendElementRectSnapshot(values, documentSurface?.element ?? null);

    try {
      const surfaceSnapshot = documentSurface?.readSettleSnapshot?.();
      if (surfaceSnapshot) {
        values.push(...surfaceSnapshot.map(toSettleSnapshotNumber));
      }
    } catch {
      // A renderer snapshot is diagnostic, not correctness-critical. If a
      // renderer unmounts while settling, fall back to shell geometry.
    }

    return values.length > 0 ? values : [0];
  }

  function appendElementRectSnapshot(
    values: number[],
    element: HTMLElement | null,
  ) {
    if (!readElementRectSnapshot || !element) return;
    for (const value of readElementRectSnapshot(element)) {
      values.push(toSettleSnapshotNumber(value));
    }
  }
}

function areSettleSnapshotsEqual(
  previous: readonly number[],
  next: readonly number[],
) {
  if (previous.length !== next.length) return false;
  return previous.every(
    (value, index) =>
      Math.abs(value - next[index]) <= FILE_VIEWER_SETTLE_SCROLL_EPSILON_PX,
  );
}

function toSettleSnapshotNumber(value: number) {
  return Number.isFinite(value) ? value : 0;
}

function shouldDispatchBeforeLayoutMotion({
  currentRestFrame,
  nextRestFrame,
}: FileViewerMotionPlan) {
  return (
    currentRestFrame.mode === "inline" &&
    nextRestFrame.mode === "inline" &&
    Math.abs(
      currentRestFrame.layoutInlineSize - nextRestFrame.layoutInlineSize,
    ) > 0.001
  );
}

export function useFileViewerMotionFrame(
  kernel: FileViewerMotionKernel | null | undefined,
): FileViewerMotionFrame {
  const subscribe = React.useCallback(
    (listener: () => void) => kernel?.subscribe(listener) ?? (() => {}),
    [kernel],
  );
  const getSnapshot = React.useCallback(
    () => kernel?.getSnapshot() ?? DEFAULT_FILE_VIEWER_MOTION_FRAME,
    [kernel],
  );

  return React.useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

function prefersReducedMotion() {
  return (
    typeof matchMedia === "function" &&
    matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

function readNow() {
  return typeof performance !== "undefined" &&
    typeof performance.now === "function"
    ? performance.now()
    : Date.now();
}

function getRequestAnimationFrame() {
  return (
    globalThis.requestAnimationFrame ??
    ((callback: FrameRequestCallback) =>
      window.setTimeout(() => callback(readNow()), 16))
  );
}

function getCancelAnimationFrame() {
  return (
    globalThis.cancelAnimationFrame ??
    ((id: number) => {
      window.clearTimeout(id);
    })
  );
}

function lerp(from: number, to: number, progress: number) {
  return from + (to - from) * progress;
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

"use client";

import * as React from "react";
import { PanelLeft, PanelRight } from "lucide-react";

import { cn } from "@/lib/utils";

import { Button } from "./button";
import { Spinner } from "./spinner";
import { useFileViewerControlsState } from "./file-viewer-controls-context";
import { useFileViewerRequiredResourceState } from "./file-viewer-resource-state";
import {
  useFileViewerContext,
  useFileViewerShell,
} from "./file-viewer-context";
import { resolveFileViewerSidebarTriggerAccessibilityProps } from "./file-viewer-accessibility";
import { ViewerControls } from "./viewer-controls";
import { ViewerHeaderOutlet } from "./viewer-header-outlet";

type ButtonProps = React.ComponentProps<typeof Button> & {
  loading?: boolean;
};

export type FileViewerHeaderProps = React.ComponentProps<"div">;
export type FileViewerTitleProps = React.ComponentProps<"span">;
export type FileViewerMetaProps = React.ComponentProps<"span"> & {
  visibility?: "responsive" | "visible";
};
export type FileViewerControlsProps = Omit<
  React.ComponentProps<typeof ViewerControls>,
  | "downloads"
  | "loading"
  | "position"
  | "rotate"
  | "subtitle"
  | "title"
  | "zoom"
>;
export type FileViewerSidebarTriggerProps = ButtonProps;

export function FileViewerHeader({
  children,
  className,
  ...props
}: FileViewerHeaderProps) {
  const { hasHeaderOutlets, headerMode } = useFileViewerContext();
  const content = children ?? <FileViewerDefaultHeaderContent />;

  if (headerMode === "outlets" && hasHeaderOutlets) {
    return <>{content}</>;
  }

  return (
    <div
      data-slot="file-viewer-header"
      className={cn(
        "bg-card flex min-h-10 shrink-0 flex-wrap items-center gap-2 border-b px-2 py-1 sm:flex-nowrap sm:py-0",
        className,
      )}
      {...props}
    >
      {content}
    </div>
  );
}

function FileViewerDefaultHeaderContent() {
  const { hasHeaderOutlets, headerMode } = useFileViewerContext();

  if (headerMode === "outlets" && hasHeaderOutlets) {
    return (
      <>
        <FileViewerTitle />
        <FileViewerMeta />
        <FileViewerControls />
      </>
    );
  }

  return (
    <>
      <div
        data-slot="file-viewer-header-title-group"
        className="flex min-w-0 flex-1 items-baseline gap-2"
      >
        <FileViewerTitle />
        <FileViewerMeta />
      </div>
      <FileViewerControls />
    </>
  );
}

export function FileViewerTitle({ className, ...props }: FileViewerTitleProps) {
  const { hasHeaderOutlets, headerMode } = useFileViewerContext();
  const { descriptor } = useFileViewerRequiredResourceState();
  const title = (
    <span
      data-slot="file-viewer-title"
      className={cn(
        "text-foreground min-w-0 truncate text-[13px] leading-5 font-medium",
        className,
      )}
      title={descriptor.displayName}
      {...props}
    >
      {descriptor.displayName}
    </span>
  );

  if (headerMode === "outlets" && hasHeaderOutlets) {
    return <ViewerHeaderOutlet name="titleGroup">{title}</ViewerHeaderOutlet>;
  }

  return title;
}

export function FileViewerMeta({
  className,
  visibility = "responsive",
  ...props
}: FileViewerMetaProps) {
  const { hasHeaderOutlets, headerMode } = useFileViewerContext();
  const { descriptor, resource } = useFileViewerRequiredResourceState();
  const metaText =
    resource.mimeType || descriptor.mimeType || descriptor.category;

  if (!metaText) return null;

  const meta = (
    <span
      data-slot="file-viewer-meta"
      className={cn(
        "text-muted-foreground min-w-0 shrink truncate text-xs",
        visibility === "responsive" && "hidden sm:inline",
        className,
      )}
      {...props}
    >
      {metaText}
    </span>
  );

  if (headerMode === "outlets" && hasHeaderOutlets) {
    return <ViewerHeaderOutlet name="titleGroup">{meta}</ViewerHeaderOutlet>;
  }

  return meta;
}

export function FileViewerControls({
  className,
  extra,
  ...props
}: FileViewerControlsProps) {
  const { resource } = useFileViewerRequiredResourceState();
  const controlsState = useFileViewerControlsState();
  const downloads = controlsState?.downloads ?? [resource.originalDownload];
  const { hasHeaderOutlets, headerMode } = useFileViewerContext();

  const controls = (
    <ViewerControls
      {...props}
      data-file-viewer-controls={controlsState ? "ready" : "idle"}
      data-slot="file-viewer-controls"
      className={cn(
        "ms-auto h-8 min-w-0 border-b-0 bg-transparent px-0",
        className,
      )}
      downloads={downloads}
      extra={extra ?? controlsState?.extra}
      loading={controlsState?.loading ?? false}
      position={controlsState?.position ?? null}
      rotate={controlsState?.rotate ?? null}
      zoom={controlsState?.zoom ?? null}
    />
  );

  if (headerMode === "outlets" && hasHeaderOutlets) {
    return <ViewerHeaderOutlet name="controls">{controls}</ViewerHeaderOutlet>;
  }

  return controls;
}

export function FileViewerSidebarTrigger({
  className,
  disabled,
  loading,
  onClick,
  children,
  size = "icon",
  variant = "ghost",
  "aria-label": ariaLabel = "Toggle sidebar",
  ...props
}: FileViewerSidebarTriggerProps) {
  const {
    canToggleSidebar,
    elementRegistry,
    mode,
    side,
    isSidebarInteractive,
    sidebarId,
    sidebarState,
    toggleSidebarRequestedOpen,
  } = useFileViewerShell("FileViewerSidebarTrigger");
  const isDisabled = Boolean(disabled || loading || !canToggleSidebar);
  const Icon = side === "right" ? PanelRight : PanelLeft;
  const setTriggerElement = React.useCallback(
    (element: HTMLButtonElement | null) => {
      elementRegistry.registerSidebarTriggerElement(element);
    },
    [elementRegistry],
  );
  const accessibilityProps = resolveFileViewerSidebarTriggerAccessibilityProps({
    ariaLabel,
    canToggleSidebar,
    isDisabled,
    isSidebarInteractive,
    sidebarId,
  });

  return (
    <Button
      ref={setTriggerElement}
      {...accessibilityProps}
      className={cn("size-8", className)}
      data-file-viewer-sidebar-mode={mode}
      data-file-viewer-sidebar-side={side}
      data-file-viewer-sidebar-state={sidebarState}
      data-side={side}
      data-slot="file-viewer-sidebar-trigger"
      disabled={isDisabled}
      onClick={(event) => {
        if (isDisabled) {
          event.preventDefault();
          return;
        }

        onClick?.(event);
        if (!event.defaultPrevented) {
          toggleSidebarRequestedOpen();
        }
      }}
      size={size}
      variant={variant}
      {...props}
    >
      {loading ? <Spinner className="size-4 animate-spin" /> : null}
      {children ?? (
        <>
          {loading ? null : <Icon />}
          <span className="sr-only">Toggle sidebar</span>
        </>
      )}
    </Button>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import {
  viewerContentRenderKey,
  type ViewerResource,
} from "@/lib/viewer-resource";

import { ViewerFallback } from "./file-viewer-fallback";
import { getHtmlViewerSrcDoc } from "./file-viewer-html-srcdoc-cache";
import { loadTextResource } from "./file-viewer-text-resource";
import { isAbortError } from "./viewer-abortable-request";
import { useViewerControlsRegistration } from "./viewer-controls";
import { useZoom, ZoomActions } from "./viewer-zoom";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

type HtmlLoadState =
  | { status: "loading"; key: unknown }
  | { status: "loaded"; key: unknown; html: string }
  | { status: "error"; key: unknown; error: unknown };

export function HtmlFileContent({
  resource,
  className,
  bare,
  controls = true,
  descriptorSignal,
}: {
  resource: ViewerResource;
  className?: string;
  bare?: boolean;
  controls?: boolean;
  descriptorSignal: AbortSignal;
}) {
  if (resource.content.payload.kind === "text") {
    return (
      <HtmlFileContentFrame
        key={viewerContentRenderKey(resource.content)}
        resource={resource}
        html={resource.content.payload.text}
        className={className}
        bare={bare}
        controls={controls}
      />
    );
  }
  return (
    <HtmlFileResource
      resource={resource}
      className={className}
      bare={bare}
      controls={controls}
      descriptorSignal={descriptorSignal}
    />
  );
}

function HtmlFileResource({
  resource,
  className,
  bare,
  controls,
  descriptorSignal,
}: {
  resource: ViewerResource;
  className?: string;
  bare?: boolean;
  controls: boolean;
  descriptorSignal: AbortSignal;
}) {
  const content = resource.content;
  const contentKey = content.key;
  const [state, setState] = React.useState<HtmlLoadState>({
    status: "loading",
    key: contentKey,
  });

  useKeyedMountEffect(
    joinEffectKey([content, contentKey, descriptorSignal, resource.fileName]),
    () => {
      let active = true;
      const controller = new AbortController();
      const abortLocal = () => controller.abort();
      setState({ status: "loading", key: contentKey });

      if (descriptorSignal.aborted) {
        abortLocal();
      } else {
        descriptorSignal.addEventListener("abort", abortLocal, { once: true });
      }

      loadTextResource({
        content,
        fileName: resource.fileName,
        signal: controller.signal,
      }).then(
        (html) => {
          if (active && !controller.signal.aborted) {
            setState({ status: "loaded", key: contentKey, html });
          }
        },
        (error: unknown) => {
          if (!active || isAbortError(error)) return;
          setState({ status: "error", key: contentKey, error });
        },
      );

      return () => {
        active = false;
        descriptorSignal.removeEventListener("abort", abortLocal);
        abortLocal();
      };
    },
  );

  if (state.key !== contentKey) {
    return (
      <ViewerFallback resource={resource} className={className} bare={bare} />
    );
  }
  if (state.status === "error") {
    throw state.error;
  }
  if (state.status === "loading") {
    return (
      <ViewerFallback resource={resource} className={className} bare={bare} />
    );
  }

  const { html } = state;
  return (
    <HtmlFileContentFrame
      key={contentKey}
      resource={resource}
      html={html}
      className={className}
      bare={bare}
      controls={controls}
    />
  );
}

function HtmlFileContentFrame({
  resource,
  html,
  className,
  bare,
  controls,
}: {
  resource: ViewerResource;
  html: string;
  className?: string;
  bare?: boolean;
  controls: boolean;
}) {
  const fileName = resource.fileName;
  const { scale, zoom, reset } = useZoom();
  useHtmlControlsRegistration({ reset, scale, zoom });

  return (
    <div
      data-slot="html-file-viewer-content"
      className={cn(
        "bg-card flex min-h-0 flex-1 flex-col overflow-hidden",
        bare ? "h-full" : "min-h-64",
        className,
      )}
    >
      {controls ? (
        <HtmlContentToolbar scale={scale} zoom={zoom} reset={reset} />
      ) : null}
      <SandboxedDoc
        contentKey={resource.content.key}
        html={html}
        title={fileName}
        scale={scale}
      />
    </div>
  );
}

function useHtmlControlsRegistration({
  reset,
  scale,
  zoom,
}: {
  reset: () => void;
  scale: number;
  zoom: (factor: number) => void;
}) {
  const onControlsChange = useViewerControlsRegistration();

  useKeyedMountEffect(
    joinEffectKey([onControlsChange, reset, scale, zoom]),
    () => {
      if (!onControlsChange) return;

      onControlsChange({
        zoom: {
          scale,
          onZoomOut: () => zoom(1 / 1.2),
          onZoomIn: () => zoom(1.2),
          onReset: reset,
        },
      });

      return () => onControlsChange(null);
    },
  );
}

function HtmlContentToolbar({
  scale,
  zoom,
  reset,
}: {
  scale: number;
  zoom: (factor: number) => void;
  reset: () => void;
}) {
  return (
    <div className="bg-card flex h-10 shrink-0 items-center justify-end gap-1 border-b px-2">
      <ZoomActions scale={scale} zoom={zoom} reset={reset} />
    </div>
  );
}

function SandboxedDoc({
  contentKey,
  html,
  title,
  scale = 1,
}: {
  contentKey: string;
  html: string;
  title: string;
  scale?: number;
}) {
  const { containerRef, shouldMountIframe } =
    useLazySandboxedIframeMount(contentKey);
  const srcDoc = React.useMemo(
    () =>
      shouldMountIframe
        ? getHtmlViewerSrcDoc({
            contentKey,
            html,
          })
        : "",
    [contentKey, html, shouldMountIframe],
  );

  return (
    <div
      ref={containerRef}
      className="bg-document flex min-h-0 flex-1 flex-col overflow-auto"
    >
      {shouldMountIframe ? (
        <iframe
          sandbox=""
          srcDoc={srcDoc}
          title={title}
          className="bg-document h-full min-h-0 w-full flex-1 border-0"
          style={{ zoom: scale }}
        />
      ) : null}
    </div>
  );
}

function useLazySandboxedIframeMount(resetKey: string) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [shouldMountIframe, setShouldMountIframe] = React.useState(false);
  const mountEffectKey = shouldMountIframe
    ? null
    : joinEffectKey(["html-iframe-visible", resetKey]);

  useKeyedMountEffect(mountEffectKey, () => {
    if (typeof IntersectionObserver === "undefined") {
      setShouldMountIframe(true);
      return;
    }

    const node = containerRef.current;
    if (!node) {
      setShouldMountIframe(true);
      return;
    }

    let observer: IntersectionObserver | null = null;
    try {
      observer = new IntersectionObserver(
        (entries) => {
          if (
            entries.some(
              (entry) => entry.isIntersecting || entry.intersectionRatio > 0,
            )
          ) {
            setShouldMountIframe(true);
            observer?.disconnect();
          }
        },
        { rootMargin: "512px" },
      );
    } catch {
      setShouldMountIframe(true);
      return;
    }

    observer.observe(node);

    return () => observer.disconnect();
  });

  return { containerRef, shouldMountIframe };
}

import { lruGet, lruSet } from "./viewer-lru-cache";

const HTML_VIEWER_SRC_DOC_IDENTITIES_PER_CONTENT = 2;

const HTML_VIEWER_DOCUMENT_STYLE = `<style data-retab-html-viewer-padding>
html {
  background: white;
}
body {
  box-sizing: border-box;
  margin: 0;
  min-width: 0;
  padding: 1rem;
}
body > :first-child {
  margin-block-start: 0;
}
body > :last-child {
  margin-block-end: 0;
}
</style>`;

interface HtmlViewerSrcDocCacheEntry {
  readonly html: string;
  readonly srcDoc: string;
}

interface HtmlViewerSrcDocCacheBucket {
  readonly entries: HtmlViewerSrcDocCacheEntry[];
}

const htmlViewerSrcDocCache = new Map<string, HtmlViewerSrcDocCacheBucket>();
let htmlViewerSrcDocCacheHitsForTests = 0;
let htmlViewerSrcDocCacheMissesForTests = 0;

export function getHtmlViewerSrcDoc({
  contentKey,
  html,
}: {
  contentKey: string;
  html: string;
}) {
  const bucket = lruGet(htmlViewerSrcDocCache, contentKey);
  const cached = bucket?.entries.find((entry) => entry.html === html);

  if (cached) {
    htmlViewerSrcDocCacheHitsForTests += 1;
    return cached.srcDoc;
  }

  htmlViewerSrcDocCacheMissesForTests += 1;
  const srcDoc = createHtmlViewerSrcDoc(html);
  const entries = [...(bucket?.entries ?? []), { html, srcDoc }].slice(
    -HTML_VIEWER_SRC_DOC_IDENTITIES_PER_CONTENT,
  );

  lruSet(htmlViewerSrcDocCache, contentKey, { entries });
  return srcDoc;
}

export function clearHtmlViewerSrcDocCacheForTests() {
  htmlViewerSrcDocCache.clear();
  htmlViewerSrcDocCacheHitsForTests = 0;
  htmlViewerSrcDocCacheMissesForTests = 0;
}

export function htmlViewerSrcDocCacheStatsForTests() {
  let identities = 0;
  for (const bucket of htmlViewerSrcDocCache.values()) {
    identities += bucket.entries.length;
  }

  return {
    contentKeys: htmlViewerSrcDocCache.size,
    hits: htmlViewerSrcDocCacheHitsForTests,
    identities,
    misses: htmlViewerSrcDocCacheMissesForTests,
  };
}

function createHtmlViewerSrcDoc(html: string) {
  const headOpenTag = /<head(?:\s[^>]*)?>/i;
  const htmlOpenTag = /<html(?:\s[^>]*)?>/i;

  if (headOpenTag.test(html)) {
    return html.replace(
      headOpenTag,
      (tag) => `${tag}${HTML_VIEWER_DOCUMENT_STYLE}`,
    );
  }
  if (htmlOpenTag.test(html)) {
    return html.replace(
      htmlOpenTag,
      (tag) => `${tag}<head>${HTML_VIEWER_DOCUMENT_STYLE}</head>`,
    );
  }
  return `${HTML_VIEWER_DOCUMENT_STYLE}${html}`;
}

