export type FileViewerRouteProps = {
  className?: string;
  descriptor: FileDescriptor;
  descriptorSignal: AbortSignal;
  fallbackFrameSize?: FileViewerFallbackSize;
  fallbackSlideSize?: FileViewerFallbackSize;
  frame?: "contained" | "none";
  isolateStyles: boolean;
  resource: ViewerResource;
  controls: boolean;
};

type RenderContext = {
  descriptor: FileDescriptor;
  resource: ViewerResource;
  className?: string;
  bare: boolean;
  controls: boolean;
  fallbackFrameSize?: FileViewerFallbackSize;
  fallbackSlideSize?: FileViewerFallbackSize;
  isolateStyles: boolean;
  descriptorSignal: AbortSignal;
};

// Categories a text-kind source (raw text, no blob/url backing) can render.
const TEXT_SOURCE_CATEGORIES = new Set<FileCategory>([
  "csv",
  "markdown",
  "html",
  "text",
]);

const RENDERERS: Partial<
  Record<FileCategory, (ctx: RenderContext) => React.ReactNode>
> = {
  pdf: ({ resource, className, bare, controls }) => (
    <PdfResourceContent
      resource={resource}
      className={className}
      bare={bare}
      controls={controls}
      download
    />
  ),
  docx: ({ resource, className, bare, controls }) => (
    <DocxResourceContent
      resource={resource}
      className={className}
      bare={bare}
      controls={controls}
      download
    />
  ),
  image: ({ resource, className, bare, controls, fallbackFrameSize }) => (
    <ImageResourceContent
      resource={resource}
      className={className}
      bare={bare}
      controls={controls}
      download
      fallbackFrameSize={fallbackFrameSize}
    />
  ),
  pptx: ({ resource, className, bare, controls, fallbackSlideSize }) => (
    <PptxResourceContent
      resource={resource}
      className={className}
      bare={bare}
      controls={controls}
      download
      fallbackSlideSize={fallbackSlideSize}
    />
  ),
  xlsx: ({ resource, className, bare, controls, isolateStyles }) => (
    <XlsxResourceContent
      resource={resource}
      className={className}
      bare={bare}
      controls={controls}
      download
      isolateStyles={isolateStyles}
    />
  ),
  csv: ({ resource, className, bare, controls, isolateStyles }) => (
    <CsvFileContent
      resource={resource}
      className={className}
      bare={bare}
      controls={controls}
      isolateStyles={isolateStyles}
    />
  ),
  html: ({ resource, className, bare, controls, descriptorSignal }) => (
    <HtmlFileContent
      resource={resource}
      className={className}
      bare={bare}
      controls={controls}
      descriptorSignal={descriptorSignal}
    />
  ),
  markdown: ({ resource, className, bare, controls }) => (
    <MarkdownViewer
      resource={resource}
      className={className}
      controls={controls}
      download
      bare={bare}
      urlFragmentNavigation={false}
    />
  ),
  text: renderTextViewer,
};

export function FileViewerRoute({
  descriptor,
  className,
  frame = "contained",
  isolateStyles,
  descriptorSignal,
  fallbackFrameSize,
  fallbackSlideSize,
  resource,
  controls,
}: FileViewerRouteProps) {
  const { category } = descriptor;
  const bare = frame === "none";
  const isTextSource = descriptor.source.kind === "text";

  const renderer = RENDERERS[category];
  const textSourceAllowed =
    !isTextSource || TEXT_SOURCE_CATEGORIES.has(category);
  const isRouteRenderable = Boolean(renderer) && textSourceAllowed;
  const prewarmTarget = getFileViewerPrewarmTarget({
    descriptor,
    isRouteRenderable,
  });
  useKeyedMountEffect(
    prewarmTarget
      ? joinEffectKey(["file-viewer-renderer-prewarm", prewarmTarget])
      : null,
    () => {
      if (!prewarmTarget) return;
      return scheduleFileViewerRendererPrewarm(prewarmTarget);
    },
  );

  const routeDetails = {
    bare,
    category,
    hasRenderer: Boolean(renderer),
    isTextSource,
    isolateStyles,
    source: summarizeViewerSource(descriptor.source),
    descriptor: summarizeViewerDescriptor(descriptor),
    controls,
  };
  if (renderer && textSourceAllowed) {
    fileViewerDiagnostic("debug", "file_viewer_route_renderer_selected", {
      ...routeDetails,
      textSourceAllowed,
    });
    return renderer({
      descriptor,
      resource,
      className,
      bare,
      controls,
      fallbackFrameSize,
      fallbackSlideSize,
      isolateStyles,
      descriptorSignal,
    });
  }

  fileViewerDiagnostic("warn", "file_viewer_route_unsupported", {
    ...routeDetails,
    textSourceAllowed,
  });
  return (
    <UnsupportedCard
      resource={resource}
      className={className}
      bare={bare}
      showDownload={controls}
    />
  );
}

function renderTextViewer({
  descriptor,
  resource,
  className,
  bare,
  controls,
}: RenderContext): React.ReactNode {
  if (isProseTextDescriptor(descriptor)) {
    return (
      <ProseTextViewer
        resource={resource}
        className={className}
        controls={controls}
        download
        bare={bare}
        mode="text"
      />
    );
  }
  return (
    <CodeTextViewer
      resource={resource}
      className={className}
      controls={controls}
      download
      bare={bare}
    />
  );
}

import {
  isProseTextDescriptor,
  type FileDescriptor,
  type FileCategory,
} from "./file-viewer-core";

export type FileViewerPrewarmTarget =
  | "pdf"
  | "docx"
  | "image"
  | "pptx"
  | "xlsx"
  | "markdown"
  | "text"
  | "code";

type FileViewerPrewarmStatus = "scheduled" | "running" | "complete";

type FileViewerIdleWindow = Window &
  typeof globalThis & {
    cancelIdleCallback?: Window["cancelIdleCallback"];
    requestIdleCallback?: Window["requestIdleCallback"];
  };

type FileViewerIdleTask =
  | { kind: "idle"; id: number }
  | { kind: "timeout"; id: ReturnType<typeof setTimeout> };

type FileViewerPrewarmRecord = {
  browserWindow: FileViewerIdleWindow;
  isCancelled: boolean;
  status: FileViewerPrewarmStatus;
  subscribers: number;
  task: FileViewerIdleTask | null;
};

const CATEGORY_PREWARM_TARGETS: Partial<
  Record<FileCategory, FileViewerPrewarmTarget>
> = {
  pdf: "pdf",
  docx: "docx",
  image: "image",
  pptx: "pptx",
  xlsx: "xlsx",
  markdown: "markdown",
};

const PREWARM_LOADERS: Record<FileViewerPrewarmTarget, () => Promise<void>> = {
  pdf: () => import("@/components/ui/pdf-viewer").then(() => undefined),
  docx: () => import("@/components/ui/docx-viewer").then(() => undefined),
  image: () => import("@/components/ui/image-viewer").then(() => undefined),
  pptx: () =>
    import("@/components/ui/pptx-viewer").then((module) => {
      const preloadViewer = (module as { preloadPptxViewer?: () => void })
        .preloadPptxViewer;
      preloadViewer?.();
    }),
  xlsx: () => import("@/components/ui/xlsx-viewer").then(() => undefined),
  markdown: () =>
    import("@/components/ui/markdown-viewer").then(() => undefined),
  text: () =>
    import("@/components/ui/text-viewer-chenglou").then(() => undefined),
  code: () => import("@/components/ui/code-viewer").then(() => undefined),
};

const prewarmRecords = new Map<
  FileViewerPrewarmTarget,
  FileViewerPrewarmRecord
>();

export function getFileViewerPrewarmTarget({
  descriptor,
  isRouteRenderable,
}: {
  descriptor: FileDescriptor;
  isRouteRenderable: boolean;
}): FileViewerPrewarmTarget | null {
  if (!isRouteRenderable) return null;
  if (descriptor.category === "text") {
    return isProseTextDescriptor(descriptor) ? "text" : "code";
  }
  return CATEGORY_PREWARM_TARGETS[descriptor.category] ?? null;
}

export function scheduleFileViewerRendererPrewarm(
  target: FileViewerPrewarmTarget,
): () => void {
  if (typeof window === "undefined") return noop;

  const existingRecord = prewarmRecords.get(target);
  if (existingRecord) {
    if (existingRecord.status !== "scheduled") return noop;
    existingRecord.subscribers += 1;
    return () => releaseScheduledPrewarm(target, existingRecord);
  }

  const browserWindow = window as FileViewerIdleWindow;
  const record: FileViewerPrewarmRecord = {
    browserWindow,
    isCancelled: false,
    status: "scheduled",
    subscribers: 1,
    task: null,
  };
  record.task = scheduleIdleTask(browserWindow, () => {
    if (record.isCancelled) return;
    record.status = "running";
    record.task = null;
    void PREWARM_LOADERS[target]()
      .then(() => {
        if (prewarmRecords.get(target) === record) {
          record.status = "complete";
        }
      })
      .catch(() => {
        if (prewarmRecords.get(target) === record) {
          prewarmRecords.delete(target);
        }
      });
  });
  prewarmRecords.set(target, record);

  return () => releaseScheduledPrewarm(target, record);
}

export function resetFileViewerRendererPrewarmForTests() {
  prewarmRecords.clear();
}

function releaseScheduledPrewarm(
  target: FileViewerPrewarmTarget,
  record: FileViewerPrewarmRecord,
) {
  if (prewarmRecords.get(target) !== record || record.status !== "scheduled") {
    return;
  }
  record.subscribers -= 1;
  if (record.subscribers > 0) return;

  record.isCancelled = true;
  if (record.task) cancelIdleTask(record.browserWindow, record.task);
  prewarmRecords.delete(target);
}

function scheduleIdleTask(
  browserWindow: FileViewerIdleWindow,
  callback: () => void,
): FileViewerIdleTask {
  if (browserWindow.requestIdleCallback) {
    return {
      kind: "idle",
      id: browserWindow.requestIdleCallback(callback, { timeout: 600 }),
    };
  }
  return { kind: "timeout", id: setTimeout(callback, 120) };
}

function cancelIdleTask(
  browserWindow: FileViewerIdleWindow,
  task: FileViewerIdleTask,
) {
  if (task.kind === "idle") {
    browserWindow.cancelIdleCallback?.(task.id);
    return;
  }
  clearTimeout(task.id);
}

function noop() {}

