}

export function createViewerGeometryStore(): ViewerGeometryStore {
  const listeners = new Set<() => void>();
  let snapshot = DEFAULT_VIEWER_GEOMETRY_SNAPSHOT;
  let transitionTargetSnapshot: ViewerGeometryBaseSnapshot | null = null;
  let transitionFrame = 0;
  let transitionStartTime: number | null = null;
  let transitionStartSidebarInlineSize =
    DEFAULT_VIEWER_GEOMETRY_SNAPSHOT.sidebarInlineSize;

  const notify = () => {
    for (const listener of listeners) listener();
  };

  const commitSnapshot = (nextSnapshot: ViewerGeometrySnapshot) => {
    if (areViewerGeometrySnapshotsEqual(snapshot, nextSnapshot)) return;

    snapshot = nextSnapshot;
    notify();
  };

  const cancelTransitionFrame = () => {
    if (transitionFrame === 0) return;
    const cancelAnimationFrame =
      globalThis.cancelAnimationFrame ??
      (typeof window === "undefined" ? undefined : window.cancelAnimationFrame);
    cancelAnimationFrame?.(transitionFrame);
    transitionFrame = 0;
  };

  const commitGeometryProgress = (progress: number) => {
    if (!transitionTargetSnapshot) return;

    const sidebarInlineSize = lerp(
      transitionStartSidebarInlineSize,
      transitionTargetSnapshot.sidebarInlineSize,
      progress,
    );

    commitSnapshot({
      ...transitionTargetSnapshot,
      documentInlineSize: getViewerGeometryDocumentInlineSize({
        bodyInlineSize: transitionTargetSnapshot.bodyInlineSize,
        mode: transitionTargetSnapshot.mode,
        sidebarGapTransition: transitionTargetSnapshot.sidebarGapTransition,
        sidebarInlineSize,
      }),
      isTransitioning: progress < 1,
      progress,
      sidebarInlineSize,
      transitionPhase: progress < 1 ? "sliding" : "idle",
    });

    if (progress >= 1) {
      transitionTargetSnapshot = null;
    }
  };

  const scheduleTransitionFrame = () => {
    const requestAnimationFrame =
      globalThis.requestAnimationFrame ??
      (typeof window === "undefined" ? undefined : window.requestAnimationFrame);

    if (typeof requestAnimationFrame !== "function") {
      commitGeometryProgress(1);
      return;
    }

    transitionFrame = requestAnimationFrame((timestamp) => {
      transitionFrame = 0;
      if (!transitionTargetSnapshot) return;
      if (transitionStartTime === null) transitionStartTime = timestamp;

      const progress = clamp01(
        (timestamp - transitionStartTime) / VIEWER_GEOMETRY_TRANSITION_MS,
      );
      commitGeometryProgress(progress);

      if (progress < 1) scheduleTransitionFrame();
    });
  };

  const startTransition = (targetSnapshot: ViewerGeometryBaseSnapshot) => {
    cancelTransitionFrame();

    transitionTargetSnapshot = targetSnapshot;
    transitionStartSidebarInlineSize = snapshot.sidebarInlineSize;
    transitionStartTime = readViewerGeometryNow();

    commitGeometryProgress(0);
    scheduleTransitionFrame();
  };

  return {
    getSnapshot: () => snapshot,
    setTarget: (target) => {
      const resolvedSidebarWidth =
        Number.isFinite(target.sidebarWidth) && target.sidebarWidth > 0
          ? target.sidebarWidth
          : readViewerGeometrySidebarWidth(target);
      const sidebarWidth =
        resolvedSidebarWidth > 0 ? resolvedSidebarWidth : snapshot.sidebarWidth;
      const measuredBodyInlineSize = readViewerGeometryBodyInlineSize(target);
      const bodyInlineSize =
        measuredBodyInlineSize > 0
          ? measuredBodyInlineSize
          : snapshot.bodyInlineSize;
      const hasMeasuredBody =
        measuredBodyInlineSize > 0 || snapshot.hasMeasuredBody;
      const sidebarInlineSize = getViewerGeometryTargetSidebarInlineSize({
        mode: target.mode,
        open: target.open,
        sidebarGapTransition: target.sidebarGapTransition,
        sidebarWidth,
      });
      const nextBaseSnapshot: ViewerGeometryBaseSnapshot = {
        bodyInlineSize,
        documentInlineSize: getViewerGeometryDocumentInlineSize({
          bodyInlineSize,
          mode: target.mode,
          sidebarGapTransition: target.sidebarGapTransition,
          sidebarInlineSize,
        }),
        hasMeasuredBody,
        mode: target.mode,
        open: target.open,
        sidebarGapTransition: target.sidebarGapTransition,
        sidebarInlineSize,
        sidebarWidth,
        side: target.side,
        state: target.state,
      };

      if (
        snapshot.isTransitioning &&
        transitionTargetSnapshot &&
        areViewerGeometryTargetsEqual(
          transitionTargetSnapshot,
          nextBaseSnapshot,
        )
      ) {
        return;
      }

      const shouldAnimate = shouldAnimateViewerGeometry({
        previousSnapshot: snapshot,
        targetSnapshot: nextBaseSnapshot,
      });

      if (!shouldAnimate) {
        cancelTransitionFrame();
        transitionTargetSnapshot = null;
        commitSnapshot({
          ...nextBaseSnapshot,
          isTransitioning: false,
          progress: 1,
          transitionPhase: "idle",
        });
        return;
      }

      startTransition(nextBaseSnapshot);
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}

export function resolveSidebarMode({
  requestedMode,
  width,
  inlineBreakpoint,
}: {
  requestedMode: ViewerSidebarRequestedMode;
  width: number | null;
  inlineBreakpoint: number;
}): ViewerSidebarMode {
  if (requestedMode !== "auto") return requestedMode;
  if (width === null) return "overlay";
  return width >= inlineBreakpoint ? "inline" : "overlay";
}

export function resolveMeasuredSidebarMode({
  currentMode,
  hasMeasured,
  inlineBreakpoint,
  requestedMode,
  width,
}: {
  currentMode: ViewerSidebarMode;
  hasMeasured: boolean;
  inlineBreakpoint: number;
  requestedMode: ViewerSidebarRequestedMode;
  width: number;
}): ViewerSidebarMode {
  if (requestedMode !== "auto") return requestedMode;
  if (!hasMeasured) {
    return width >= inlineBreakpoint ? "inline" : "overlay";
  }

  if (currentMode === "inline") {
    return width < inlineBreakpoint - VIEWER_SIDEBAR_MODE_HYSTERESIS
      ? "overlay"
      : "inline";
  }

  return width > inlineBreakpoint + VIEWER_SIDEBAR_MODE_HYSTERESIS
    ? "inline"
    : "overlay";
}

export function isAriaDisabled(value: unknown): boolean {
  return value === true || value === "true";
}

export function pickCssCustomProperties(
  style: React.CSSProperties | undefined,
): React.CSSProperties {
  if (!style) return {};

  return Object.fromEntries(
    Object.entries(style).filter(([name]) => name.startsWith("--")),
  ) as React.CSSProperties;
}

function isViewerStateNamespaceEnabled(
  namespace: ViewerStateAttributeNamespace | undefined,
  slot: ViewerStateAttributeSlot,
): namespace is ViewerStateAttributeNamespace {
  if (!namespace) return false;
  return namespace.slots?.[slot] ?? true;
}

export function createViewerStateAttributes(
  namespace: ViewerStateAttributeNamespace | undefined,
  slot: ViewerStateAttributeSlot,
  values: ViewerStateAttributeValues,
): ViewerDataAttributes {
  if (!isViewerStateNamespaceEnabled(namespace, slot)) return {};

  const attributes: ViewerDataAttributes = {};
  const prefix = namespace.prefix;

  if (values.hasSidebar !== undefined) {
    attributes[`data-${prefix}-has-sidebar`] = values.hasSidebar
      ? "true"
      : "false";
  }
  if (values.sidebarCollapsible !== undefined) {
    attributes[`data-${prefix}-sidebar-collapsible`] =
      values.sidebarCollapsible;
  }
  if (values.sidebarMode !== undefined) {
    attributes[`data-${prefix}-sidebar-mode`] = values.sidebarMode;
  }
  if (values.sidebarOpen !== undefined) {
    attributes[`data-${prefix}-sidebar-open`] = values.sidebarOpen
      ? "true"
      : "false";
  }
  if (values.sidebarSide !== undefined) {
    attributes[`data-${prefix}-sidebar-side`] = values.sidebarSide;
  }
  if (values.sidebarState !== undefined) {
    attributes[`data-${prefix}-sidebar-state`] = values.sidebarState;
  }

  return attributes;
}

export function createViewerSlotAttributes(
  namespace: ViewerStateAttributeNamespace | undefined,
  slot: ViewerStateAttributeSlot,
  value: string | undefined,
): ViewerDataAttributes {
  if (!value || !isViewerStateNamespaceEnabled(namespace, slot)) return {};
  return {
    [`data-${namespace.prefix}-slot`]: value,
  };
}

export function createViewerPortalContainmentAttributes(
  rootId: string,
): ViewerPortalContainmentAttributes {
  return {
    [VIEWER_PORTAL_ROOT_ID_ATTRIBUTE]: rootId,
  };
}

export function readViewerElementSize(element: HTMLElement | null) {
  if (!element) return { height: 0, width: 0 };

  const rect =
    typeof element.getBoundingClientRect === "function"
      ? element.getBoundingClientRect()
      : null;
  return {
    height: rect?.height || element.clientHeight || 0,
    width: rect?.width || element.clientWidth || 0,
  };
}

function readViewerGeometrySidebarWidth({
  rootElement,
  sidebarElement,
}: ViewerGeometryTarget) {
  const elementSize = readViewerElementSize(sidebarElement);
  if (Number.isFinite(elementSize.width) && elementSize.width > 0) {
    return elementSize.width;
  }

  return readViewerSidebarDeclaredWidth(rootElement, sidebarElement);
}

function readViewerGeometryBodyInlineSize({
  bodyElement,
  rootElement,
}: ViewerGeometryTarget) {
  const bodySize = readViewerElementSize(bodyElement);
  if (Number.isFinite(bodySize.width) && bodySize.width > 0) {
    return bodySize.width;
  }

  const rootSize = readViewerElementSize(rootElement);
  return Number.isFinite(rootSize.width) && rootSize.width > 0
    ? rootSize.width
    : 0;
}

function readViewerSidebarDeclaredWidth(
  rootElement: HTMLElement | null,
  sidebarElement: HTMLElement | null,
) {
  return (
    readViewerCssLength(rootElement, "--viewer-sidebar-width") ??
    readViewerCssLength(sidebarElement, "--viewer-sidebar-width") ??
    0
  );
}

function readViewerCssLength(
  element: HTMLElement | null,
  propertyName: string,
) {
  if (!element || typeof window === "undefined") return null;

  const styleValue = element.style.getPropertyValue(propertyName);
  const computedValue =
    window.getComputedStyle(element).getPropertyValue(propertyName);
  return parseViewerCssLength(styleValue) ?? parseViewerCssLength(computedValue);
}

function parseViewerCssLength(value: string) {
  const trimmedValue = value.trim();
  if (!trimmedValue.endsWith("px")) return null;

  const length = Number.parseFloat(trimmedValue);
  return Number.isFinite(length) && length > 0 ? length : null;
}

function areViewerGeometrySnapshotsEqual(
  previous: ViewerGeometrySnapshot,
  next: ViewerGeometrySnapshot,
) {
  return (
    previous.bodyInlineSize === next.bodyInlineSize &&
    previous.documentInlineSize === next.documentInlineSize &&
    previous.hasMeasuredBody === next.hasMeasuredBody &&
    previous.isTransitioning === next.isTransitioning &&
    previous.mode === next.mode &&
    previous.open === next.open &&
    previous.progress === next.progress &&
    previous.sidebarGapTransition === next.sidebarGapTransition &&
    previous.sidebarInlineSize === next.sidebarInlineSize &&
    previous.sidebarWidth === next.sidebarWidth &&
    previous.side === next.side &&
    previous.state === next.state &&
    previous.transitionPhase === next.transitionPhase
  );
}

function areViewerGeometryTargetsEqual(
  previous: ViewerGeometryBaseSnapshot,
  next: ViewerGeometryBaseSnapshot,
) {
  return (
    previous.bodyInlineSize === next.bodyInlineSize &&
    previous.documentInlineSize === next.documentInlineSize &&
    previous.hasMeasuredBody === next.hasMeasuredBody &&
    previous.mode === next.mode &&
    previous.open === next.open &&
    previous.sidebarGapTransition === next.sidebarGapTransition &&
    previous.sidebarInlineSize === next.sidebarInlineSize &&
    previous.sidebarWidth === next.sidebarWidth &&
    previous.side === next.side &&
    previous.state === next.state
  );
}

function shouldAnimateViewerGeometry({
  previousSnapshot,
  targetSnapshot,
}: {
  previousSnapshot: ViewerGeometrySnapshot;
  targetSnapshot: ViewerGeometryBaseSnapshot;
}) {
  return (
    previousSnapshot.sidebarWidth > 0 &&
    targetSnapshot.mode === "inline" &&
    targetSnapshot.sidebarGapTransition === "width" &&
    targetSnapshot.sidebarWidth > 0 &&
    hasViewerGeometryAnimationSupport() &&
    !prefersReducedViewerGeometryMotion() &&
    !areViewerGeometryInlineSizesEqual(
      previousSnapshot.sidebarInlineSize,
      targetSnapshot.sidebarInlineSize,
    )
  );
}

function getViewerGeometryTargetSidebarInlineSize(
  snapshot: Pick<
    ViewerGeometryBaseSnapshot,
    "mode" | "open" | "sidebarGapTransition" | "sidebarWidth"
  >,
) {
  return snapshot.mode === "inline" && snapshot.open && snapshot.sidebarWidth > 0
    ? snapshot.sidebarWidth
    : 0;
}

function getViewerGeometryDocumentInlineSize({
  bodyInlineSize,
  mode,
  sidebarGapTransition,
  sidebarInlineSize,
}: {
  bodyInlineSize: number;
  mode: ViewerSidebarMode;
  sidebarGapTransition: string;
  sidebarInlineSize: number;
}) {
  if (bodyInlineSize <= 0) return 0;
  if (mode !== "inline" || sidebarGapTransition !== "width") {
    return bodyInlineSize;
  }
  return Math.max(1, bodyInlineSize - sidebarInlineSize);
}

function areViewerGeometryInlineSizesEqual(
  previousInlineSize: number,
  nextInlineSize: number,
) {
  return Math.abs(previousInlineSize - nextInlineSize) < 0.5;
}

function hasViewerGeometryAnimationSupport() {
  const requestAnimationFrame =
    globalThis.requestAnimationFrame ??
    (typeof window === "undefined" ? undefined : window.requestAnimationFrame);
  return typeof requestAnimationFrame === "function";
}

function prefersReducedViewerGeometryMotion() {
  return (
    typeof window !== "undefined" &&
    typeof window.matchMedia === "function" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

function readViewerGeometryNow() {
  const performanceNow =
    globalThis.performance?.now ??
    (typeof window === "undefined" ? undefined : window.performance?.now);

  return typeof performanceNow === "function"
    ? performanceNow.call(globalThis.performance ?? window.performance)
    : Date.now();
}

function lerp(start: number, end: number, progress: number) {
  return start + (end - start) * progress;
}

function clamp01(value: number) {
  if (!Number.isFinite(value)) return 1;
  return Math.min(1, Math.max(0, value));
}

export function elementContainsTarget(
  element: HTMLElement | null | undefined,
  target: unknown,
): boolean {
  if (!element || target === null || target === undefined) return false;
  if (element === target) return true;

  if (typeof element.contains === "function") {
    try {
      if (element.contains(target as Node)) return true;
    } catch {
      // Some test and embedded DOM hosts do not share a Node prototype chain.
    }
  }

  if (typeof target !== "object") return false;

  let current: unknown = (target as { parentNode?: unknown }).parentNode;
  while (current && typeof current === "object") {
    if (current === element) return true;
    current = (current as { parentNode?: unknown }).parentNode;
  }

  return false;
}

export function targetHasViewerPortalContainment({
  rootId,
  target,
}: {
  rootId: string;
  target: unknown;
}): boolean {
  if (!target || typeof target !== "object") return false;

  if (typeof (target as { closest?: unknown }).closest === "function") {
    try {
      const ownerElement = (
        target as {
          closest: (selector: string) => {
            getAttribute?: (attributeName: string) => string | null;
          } | null;
        }
      ).closest(`[${VIEWER_PORTAL_ROOT_ID_ATTRIBUTE}]`);

      if (
        ownerElement?.getAttribute?.(VIEWER_PORTAL_ROOT_ID_ATTRIBUTE) === rootId
      ) {
        return true;
      }
    } catch {
      // Some test and embedded DOM hosts do not support Element.closest.
    }
  }

  let current: unknown = target;
  while (current && typeof current === "object") {
    const getAttribute = (current as { getAttribute?: unknown }).getAttribute;
    if (
      typeof getAttribute === "function" &&
      getAttribute.call(current, VIEWER_PORTAL_ROOT_ID_ATTRIBUTE) === rootId
    ) {
      return true;
    }
    current = (current as { parentNode?: unknown }).parentNode;
  }

  return false;
}

export function targetViewerRootId(target: unknown): string | null {
  if (!target || typeof target !== "object") return null;

  if (typeof (target as { closest?: unknown }).closest === "function") {
    try {
      const rootElement = (
        target as {
          closest: (selector: string) => {
            getAttribute?: (attributeName: string) => string | null;
          } | null;
        }
      ).closest(`[${VIEWER_ROOT_ID_ATTRIBUTE}]`);
      const rootId = rootElement?.getAttribute?.(VIEWER_ROOT_ID_ATTRIBUTE);
      if (rootId) return rootId;
    } catch {
      // Some test and embedded DOM hosts do not support Element.closest.
    }
  }

  let current: unknown = target;
  while (current && typeof current === "object") {
    const getAttribute = (current as { getAttribute?: unknown }).getAttribute;
    if (typeof getAttribute === "function") {
      const rootId = getAttribute.call(current, VIEWER_ROOT_ID_ATTRIBUTE);
      if (typeof rootId === "string" && rootId) {
        return rootId;
      }
    }
    current = (current as { parentNode?: unknown }).parentNode;
  }

  return null;
}

export function findClosestViewerBody(
  element: HTMLDivElement | null,
): HTMLElement | null {
  if (!element || typeof element.closest !== "function") return null;
  return element.closest<HTMLElement>('[data-viewer-slot="body"]');
}

export function useViewerDevelopmentLayoutWarning({
  enabled = true,
  elements,
  inspect,
  keyParts,
}: {
  enabled?: boolean;
  elements: () => Array<HTMLElement | null>;
  inspect: () => void;
  keyParts: unknown[];
}) {
  useKeyedLayoutEffect(enabled ? joinEffectKey(keyParts) : null, () => {
    if (process.env.NODE_ENV === "production" || !enabled) return;

    const observedElements = elements().filter(
      (element): element is HTMLElement => Boolean(element),
    );

    let frame: number | null = null;
    const run = () => {
      frame = null;
      inspect();
    };
    const schedule = () => {
      if (frame !== null) return;

      if (typeof requestAnimationFrame === "function") {
        frame = requestAnimationFrame(run);
        return;
      }

      run();
    };

    schedule();

    const ResizeObserverConstructor = globalThis.ResizeObserver;
    if (
      observedElements.length === 0 ||
      typeof ResizeObserverConstructor === "undefined"
    ) {
      return () => {
        if (frame !== null && typeof cancelAnimationFrame === "function") {
          cancelAnimationFrame(frame);
        }
      };
    }

    const observer = new ResizeObserverConstructor(schedule);
    for (const element of observedElements) {
      observer.observe(element);
    }

    return () => {
      if (frame !== null && typeof cancelAnimationFrame === "function") {
        cancelAnimationFrame(frame);
      }
      observer.disconnect();
    };
  });
}

export function useViewerSidebarRegistrationContext(
  consumer: string,
): ViewerSidebarRegistrationState {
  const context = useOptionalViewerSidebarRegistration();
  if (!context) {
    throw new Error(`${consumer} must be used within a ViewerRoot.`);
  }
  return context;
}

"use client";

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

export type StableElementSize<Element extends HTMLElement = HTMLElement> = {
  element: Element | null;
  hasMeasured: boolean;
  height: number | null;
  setElement: React.RefCallback<Element>;
  width: number | null;
};

export type StableElementSizeOptions = {
  enabled?: boolean;
  observe?: boolean;
  retainLastNonZero?: boolean;
};

export type StableCssLengthOptions = {
  element: HTMLElement | null;
  retainLastNonZero?: boolean;
  value: string;
};

type MeasuredSize = {
  height: number | null;
  width: number | null;
};

type RawMeasuredSize = {
  height: number;
  width: number;
};

// DOM layout reads for viewer chrome are quarantined in this module. The
// file-viewer motion kernel (time + style writes only) receives this reader by
// injection from the frame controller instead of touching layout APIs itself.
export function readElementRectSnapshot(
  element: HTMLElement | null,
): readonly number[] {
  if (!element) return [];
  const rect = element.getBoundingClientRect();
  return [rect.left, rect.top, rect.width, rect.height];
}

function readElementSize(element: HTMLElement): RawMeasuredSize {
  const rect =
    typeof element.getBoundingClientRect === "function"
      ? element.getBoundingClientRect()
      : null;

  return {
    height: rect?.height || element.clientHeight,
    width: rect?.width || element.clientWidth,
  };
}

function resolveMeasuredElementSize({
  currentSize,
  nextSize,
  retainLastNonZero,
}: {
  currentSize: MeasuredSize;
  nextSize: RawMeasuredSize;
  retainLastNonZero: boolean;
}): MeasuredSize {
  const width =
    Number.isFinite(nextSize.width) &&
    (!retainLastNonZero || nextSize.width > 0)
      ? nextSize.width
      : currentSize.width;
  const height =
    Number.isFinite(nextSize.height) &&
    (!retainLastNonZero || nextSize.height > 0)
      ? nextSize.height
      : currentSize.height;

  if (currentSize.width === width && currentSize.height === height) {
    return currentSize;
  }

  return { height, width };
}

export function useStableElementSize<Element extends HTMLElement = HTMLElement>(
  options: StableElementSizeOptions = {},
): StableElementSize<Element> {
  const enabled = options.enabled ?? true;
  const observe = options.observe ?? true;
  const retainLastNonZero = options.retainLastNonZero ?? false;
  const [element, setElementState] = React.useState<Element | null>(null);
  const [size, setSize] = React.useState<MeasuredSize>({
    height: null,
    width: null,
  });
  const hasMeasured = size.height !== null || size.width !== null;

  const setElement = React.useCallback((nextElement: Element | null) => {
    setElementState(nextElement);
  }, []);

  React.useLayoutEffect(() => {
    if (enabled) return;
    setSize({ height: null, width: null });
  }, [enabled]);

  useKeyedLayoutEffect(
    enabled && element
      ? joinEffectKey([element, observe, retainLastNonZero])
      : null,
    () => {
      if (!element) return;

      setSize((currentSize) =>
        resolveMeasuredElementSize({
          currentSize,
          nextSize: readElementSize(element),
          retainLastNonZero,
        }),
      );

      const ResizeObserverConstructor = observe
        ? globalThis.ResizeObserver
        : undefined;
      if (typeof ResizeObserverConstructor === "undefined") return;

      let frame = 0;
      let latestSize = readElementSize(element);
      const observer = new ResizeObserverConstructor((entries) => {
        for (const entry of entries) {
          latestSize = readElementSize(entry.target as HTMLElement);
        }

        if (frame) return;
        frame = requestAnimationFrame(() => {
          frame = 0;
          setSize((currentSize) =>
            resolveMeasuredElementSize({
              currentSize,
              nextSize: latestSize,
              retainLastNonZero,
            }),
          );
        });
      });

      observer.observe(element);

      return () => {
        if (frame) cancelAnimationFrame(frame);
        observer.disconnect();
      };
    },
  );

  return React.useMemo(
    () => ({
      element,
      hasMeasured,
      height: size.height,
      setElement,
      width: size.width,
    }),
    [element, hasMeasured, setElement, size.height, size.width],
  );
}

export function useStableCssLength({
  element,
  retainLastNonZero = true,
  value,
}: StableCssLengthOptions) {
  const [resolvedLength, setResolvedLength] = React.useState(0);

  useKeyedLayoutEffect(
    value ? joinEffectKey([element, retainLastNonZero, value]) : null,
    () => {
      const nextLength = resolveCssLength(value, element);

      setResolvedLength((currentLength) => {
        if (retainLastNonZero && nextLength <= 0) return currentLength;
        return areCssLengthsEqual(currentLength, nextLength)
          ? currentLength
          : nextLength;
      });
    },
  );

  return resolvedLength;
}

function resolveCssLength(value: string, element: HTMLElement | null) {
  const trimmedValue = value.trim();
  const pixelMatch = trimmedValue.match(/^(-?\d+(?:\.\d+)?)px$/);
  if (pixelMatch) return Math.max(0, Number(pixelMatch[1]));

  if (typeof window === "undefined") return 0;

  const remMatch = trimmedValue.match(/^(-?\d+(?:\.\d+)?)rem$/);
  if (remMatch) {
    return (
      Math.max(0, Number(remMatch[1])) *
      readComputedFontSize(window.document.documentElement)
    );
  }

  const emMatch = trimmedValue.match(/^(-?\d+(?:\.\d+)?)em$/);
  if (emMatch) {
    return Math.max(0, Number(emMatch[1])) * readComputedFontSize(element);
  }

  const measuringElement = window.document.createElement("div");
  measuringElement.style.contain = "strict";
  measuringElement.style.inlineSize = trimmedValue;
  measuringElement.style.position = "absolute";
  measuringElement.style.visibility = "hidden";
  (element ?? window.document.body).appendChild(measuringElement);
  const width = readElementInlineSize(measuringElement);
  measuringElement.remove();
  return width;
}

function readElementInlineSize(element: HTMLElement) {
  const rect =
    typeof element.getBoundingClientRect === "function"
      ? element.getBoundingClientRect()
      : null;
  const width = rect?.width || element.clientWidth || 0;
  return Number.isFinite(width) && width > 0 ? width : 0;
}

function readComputedFontSize(element: Element | null) {
  if (typeof window === "undefined") return 16;
  const fontSize = element ? window.getComputedStyle(element).fontSize : "16px";
  const value = Number.parseFloat(fontSize);
  return Number.isFinite(value) && value > 0 ? value : 16;
}

function areCssLengthsEqual(previous: number, next: number) {
  return Math.abs(previous - next) <= 0.001;
}

"use client";

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";
import { cn } from "@/lib/utils";

import {
  createViewerStateAttributes,
  createViewerPortalContainmentAttributes,
  createViewerGeometryStore,
  elementContainsTarget,
  readViewerElementSize,
  resolveMeasuredSidebarMode,
  resolveSidebarMode,
  targetHasViewerPortalContainment,
  targetViewerRootId,
  useOptionalViewerSidebarRegistration,
  useOptionalViewerSidebarState,
  useViewerSidebarState,
  VIEWER_SIDEBAR_INLINE_BREAKPOINT,
  VIEWER_SIDEBAR_WIDTH,
  ViewerSidebarRegistrationProvider,
  ViewerSidebarStateProvider,
} from "./viewer-internals";
import type {
  ViewerRootDiagnostics,
  ViewerPortalContainmentAttributes,
  ViewerRootProps,
  ViewerSidebarStateValue,
  ViewerSidebarMode,
  ViewerSidebarRegistration,
  ViewerSidebarRegistrationState,
  ViewerSidebarState,
} from "./viewer-types";

export function useViewerSidebar(): ViewerSidebarStateValue {
  return useViewerSidebarState("useViewerSidebar");
}

export function useOptionalViewerSidebar(): ViewerSidebarStateValue | null {
  return useOptionalViewerSidebarState();
}

export function useViewerPortalContainmentAttributes(): ViewerPortalContainmentAttributes {
  const context = useOptionalViewerSidebarRegistration();
  if (!context) {
    throw new Error(
      "useViewerPortalContainmentAttributes must be used within a ViewerRoot.",
    );
  }

  return React.useMemo(
    () => createViewerPortalContainmentAttributes(context.rootId),
    [context.rootId],
  );
}

export function useOptionalViewerRootDiagnostics(): ViewerRootDiagnostics | null {
  const context = useOptionalViewerSidebarRegistration();
  if (!context) return null;

  const geometry = context.geometryStore.getSnapshot();
  return {
    getRootElement: context.getRootElement,
    layoutSignature: [
      context.hasSidebar ? "sidebar" : "no-sidebar",
      context.sidebarSide,
      geometry.mode,
      geometry.open ? "open" : "closed",
      geometry.state,
    ].join(":"),
    rootId: context.rootId,
  };
}

export function ViewerRoot({
  className,
  style,
  defaultOpen = false,
  open: openProp,
  onOpenChange,
  mode = "auto",
  inlineBreakpoint = VIEWER_SIDEBAR_INLINE_BREAKPOINT,
  sidebarSide = "left",
  sidebarCollapsible = "offcanvas",
  sidebarGapTransition = "width",
  stateNamespace,
  ...props
}: ViewerRootProps) {
  const rootRef = React.useRef<HTMLDivElement | null>(null);
  const reactId = React.useId();
  const rootId = `${reactId}-viewer-root`;
  const fallbackSidebarId = `${reactId}-viewer-sidebar`;
  const isControlled = openProp !== undefined;
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen);
  const open = openProp ?? internalOpen;
  const openRef = React.useRef(open);
  openRef.current = open;
  const hasMeasuredSidebarWidthRef = React.useRef(false);
  const lastTriggerElementRef = React.useRef<HTMLElement | null>(null);
  const registeredSidebarRef = React.useRef<ViewerSidebarRegistration | null>(
    null,
  );
  const bodyElementRef = React.useRef<HTMLElement | null>(null);
  const geometryStore = React.useMemo(() => createViewerGeometryStore(), []);
  const [registeredSidebar, setRegisteredSidebar] =
    React.useState<ViewerSidebarRegistration | null>(null);
  const [bodyElement, setBodyElement] = React.useState<HTMLElement | null>(
    null,
  );
  const [resolvedSidebarMode, setResolvedSidebarMode] =
    React.useState<ViewerSidebarMode>(() =>
      resolveSidebarMode({
        requestedMode: mode,
        width: null,
        inlineBreakpoint,
      }),
    );

  const commitViewerGeometryTarget = React.useCallback(
    (nextOpen: boolean) => {
      const sidebarRegistration = registeredSidebarRef.current;
      const nextEffectiveOpen =
        sidebarRegistration?.collapsible === "none" ? true : nextOpen;
      const nextState: ViewerSidebarState = nextEffectiveOpen
        ? "expanded"
        : "collapsed";

      geometryStore.setTarget({
        bodyElement: bodyElementRef.current,
        mode: resolvedSidebarMode,
        open: nextEffectiveOpen,
        rootElement: rootRef.current,
        sidebarElement: sidebarRegistration?.element ?? null,
        sidebarGapTransition,
        sidebarWidth: sidebarRegistration?.widthPixels ?? 0,
        side: sidebarRegistration?.side ?? sidebarSide,
        state: nextState,
      });
    },
    [
      geometryStore,
      resolvedSidebarMode,
      sidebarGapTransition,
      sidebarSide,
    ],
  );

  useKeyedLayoutEffect(joinEffectKey([inlineBreakpoint, mode]), () => {
    if (mode !== "auto") {
      setResolvedSidebarMode((currentMode) =>
        currentMode === mode ? currentMode : mode,
      );
      return;
    }

    const element = rootRef.current;
    const ResizeObserverConstructor = globalThis.ResizeObserver;
    if (!element || typeof ResizeObserverConstructor === "undefined") return;

    const updateMode = () => {
      const nextWidth = readViewerElementSize(element).width;
      if (nextWidth === 0) return;

      setResolvedSidebarMode((currentMode) => {
        const nextMode = resolveMeasuredSidebarMode({
          currentMode,
          hasMeasured: hasMeasuredSidebarWidthRef.current,
          requestedMode: mode,
          width: nextWidth,
          inlineBreakpoint,
        });

        hasMeasuredSidebarWidthRef.current = true;
        return currentMode === nextMode ? currentMode : nextMode;
      });
    };

    updateMode();

    const observer = new ResizeObserverConstructor(updateMode);
    observer.observe(element);

    return () => observer.disconnect();
  });

  const setOpen = React.useCallback(
    (value: boolean | ((open: boolean) => boolean)) => {
      const previousOpen = isControlled ? open : openRef.current;
      const nextOpen =
        typeof value === "function" ? value(previousOpen) : value;

      if (nextOpen === previousOpen) {
        return;
      }

      commitViewerGeometryTarget(nextOpen);

      if (!isControlled) {
        openRef.current = nextOpen;
        setInternalOpen(nextOpen);
      }
      onOpenChange?.(nextOpen);
    },
    [commitViewerGeometryTarget, isControlled, onOpenChange, open],
  );

  const registerSidebar = React.useCallback(
    (registration: ViewerSidebarRegistration) => {
      const currentRegistration = registeredSidebarRef.current;

      if (
        currentRegistration &&
        currentRegistration.instanceId !== registration.instanceId
      ) {
        throw new Error(
          "ViewerRoot supports one primary ViewerSidebar. Use a nested ViewerRoot for a complete nested viewer, or put secondary content inside ViewerSurface.",
        );
      }

      registeredSidebarRef.current = registration;
      setRegisteredSidebar(registration);

      return () => {
        if (
          registeredSidebarRef.current?.instanceId !== registration.instanceId
        ) {
          return;
        }

        registeredSidebarRef.current = null;
        setRegisteredSidebar(null);
      };
    },
    [],
  );
  const registerBody = React.useCallback((element: HTMLElement) => {
    bodyElementRef.current = element;
    setBodyElement(element);

    return () => {
      if (bodyElementRef.current !== element) return;
      bodyElementRef.current = null;
      setBodyElement(null);
    };
  }, []);

  const toggleSidebar = React.useCallback(() => {
    setOpen((currentOpen) => !currentOpen);
  }, [setOpen]);

  const hasSidebar = registeredSidebar !== null;
  const effectiveOpen = registeredSidebar?.collapsible === "none" ? true : open;
  const state: ViewerSidebarState = effectiveOpen ? "expanded" : "collapsed";
  const canToggleSidebar =
    hasSidebar && registeredSidebar.collapsible !== "none";
  const sidebarId = registeredSidebar?.id ?? fallbackSidebarId;
  const resolvedSidebarSide = registeredSidebar?.side ?? sidebarSide;
  const sidebarWidth = registeredSidebar?.width ?? VIEWER_SIDEBAR_WIDTH;

  useKeyedLayoutEffect(
    joinEffectKey([
      effectiveOpen,
      registeredSidebar?.element,
      registeredSidebar?.widthPixels,
      bodyElement,
      resolvedSidebarMode,
      resolvedSidebarSide,
      rootRef.current,
      sidebarGapTransition,
      geometryStore,
      state,
    ]),
    () => {
      geometryStore.setTarget({
        bodyElement,
        mode: resolvedSidebarMode,
        open: effectiveOpen,
        rootElement: rootRef.current,
        sidebarElement: registeredSidebar?.element ?? null,
        sidebarGapTransition,
        sidebarWidth: registeredSidebar?.widthPixels ?? 0,
        side: resolvedSidebarSide,
        state,
      });
    },
  );
  useKeyedLayoutEffect(
    bodyElement
      ? joinEffectKey([bodyElement, commitViewerGeometryTarget, effectiveOpen])
      : null,
    () => {
      if (!bodyElement) return;
      const ResizeObserverConstructor = globalThis.ResizeObserver;
      if (typeof ResizeObserverConstructor === "undefined") {
        commitViewerGeometryTarget(effectiveOpen);
        return;
      }

      const observer = new ResizeObserverConstructor(() => {
        commitViewerGeometryTarget(effectiveOpen);
      });
      observer.observe(bodyElement);
      commitViewerGeometryTarget(effectiveOpen);

      return () => observer.disconnect();
    },
  );
  const namespacedRootStateAttributes = createViewerStateAttributes(
    stateNamespace,
    "root",
    {
      hasSidebar,
      sidebarCollapsible: registeredSidebar?.collapsible ?? sidebarCollapsible,
      sidebarMode: resolvedSidebarMode,
      sidebarOpen: effectiveOpen,
      sidebarSide: resolvedSidebarSide,
      sidebarState: state,
    },
  );
  const setLastTriggerElement = React.useCallback(
    (element: HTMLElement | null) => {
      lastTriggerElementRef.current = element;
    },
    [],
  );
  const getRootElement = React.useCallback(() => rootRef.current, []);

  useKeyedMountEffect(
    joinEffectKey([
      canToggleSidebar,
      open,
      registeredSidebar,
      resolvedSidebarMode,
      rootId,
      setOpen,
    ]),
    () => {
      if (
        !open ||
        !canToggleSidebar ||
        resolvedSidebarMode !== "overlay" ||
        typeof document === "undefined"
      ) {
        return;
      }

      const handleKeyDown = (event: KeyboardEvent) => {
        if (event.key === "Escape") {
          if (event.defaultPrevented) {
            return;
          }

          const activeElement = document.activeElement;
          if (
            activeElement &&
            rootRef.current &&
            !elementContainsTarget(rootRef.current, activeElement) &&
            !elementContainsTarget(registeredSidebar?.element, activeElement) &&
            !targetHasViewerPortalContainment({
              rootId,
              target: activeElement,
            })
          ) {
            return;
          }

          setOpen(false);
          const triggerElement =
            lastTriggerElementRef.current?.isConnected === true
              ? lastTriggerElementRef.current
              : rootRef.current?.querySelector<HTMLElement>(
                  "[data-viewer-sidebar-trigger]",
                );
          if (typeof triggerElement?.focus === "function") {
            triggerElement.focus();
          }
        }
      };
      const handlePointerDown = (event: PointerEvent) => {
        const target = event.target;

        if (elementContainsTarget(registeredSidebar?.element, target)) {
          return;
        }

        if (targetHasViewerPortalContainment({ rootId, target })) {
          return;
        }

        const targetRootId = targetViewerRootId(target);
        if (targetRootId && targetRootId !== rootId) {
          return;
        }

        if (
          target &&
          typeof (target as { closest?: unknown }).closest === "function"
        ) {
          const triggerElement = (
            target as unknown as {
              closest: (selector: string) => HTMLElement | null;
            }
          ).closest("[data-viewer-sidebar-trigger]");
          if (triggerElement?.dataset.viewerRootId === rootId) {
            return;
          }
        }

        setOpen(false);
      };

      document.addEventListener("keydown", handleKeyDown);
      document.addEventListener("pointerdown", handlePointerDown);

      return () => {
        document.removeEventListener("keydown", handleKeyDown);
        document.removeEventListener("pointerdown", handlePointerDown);
      };
    },
  );

  const sidebarStateContext = React.useMemo<ViewerSidebarStateValue>(
    () => ({
      state,
      open: effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      mode: resolvedSidebarMode,
      side: resolvedSidebarSide,
    }),
    [
      state,
      effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      resolvedSidebarMode,
      resolvedSidebarSide,
    ],
  );

  const sidebarRegistrationContext =
    React.useMemo<ViewerSidebarRegistrationState>(
      () => ({
        defaultSidebarCollapsible: sidebarCollapsible,
        defaultSidebarSide: sidebarSide,
        geometryStore,
        getRootElement,
        hasSidebar,
        registerBody,
        registerSidebar,
        rootId,
        sidebarId,
        sidebarGapTransition,
        sidebarSide: resolvedSidebarSide,
        setLastTriggerElement,
        stateNamespace,
      }),
      [
        geometryStore,
        hasSidebar,
        sidebarCollapsible,
        resolvedSidebarSide,
        getRootElement,
        registerBody,
        registerSidebar,
        rootId,
        sidebarId,
        sidebarGapTransition,
        sidebarSide,
        setLastTriggerElement,
        stateNamespace,
      ],
    );

  return (
    <ViewerSidebarStateProvider value={sidebarStateContext}>
      <ViewerSidebarRegistrationProvider value={sidebarRegistrationContext}>
        <div
          ref={rootRef}
          data-slot="viewer-root"
          data-viewer-root-id={rootId}
          data-viewer-has-sidebar={hasSidebar ? "true" : "false"}
          data-viewer-sidebar-collapsible={
            registeredSidebar?.collapsible ?? sidebarCollapsible
          }
          data-viewer-sidebar-mode={resolvedSidebarMode}
          data-viewer-sidebar-open={effectiveOpen ? "true" : "false"}
          data-viewer-sidebar-side={resolvedSidebarSide}
          data-viewer-sidebar-state={state}
          data-viewer-slot="root"
          {...namespacedRootStateAttributes}
          className={cn(
            "relative flex min-h-0 min-w-0 flex-col overflow-hidden",
            className,
          )}
          style={
            {
              overflowAnchor: "none",
              ...style,
              "--viewer-sidebar-width": sidebarWidth,
            } as React.CSSProperties
          }
          {...props}
        />
      </ViewerSidebarRegistrationProvider>
    </ViewerSidebarStateProvider>
  );
}

"use client";

import * as React from "react";

import { useMountEffect } from "@/hooks/use-mount-effect";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";
import { cn } from "@/lib/utils";

import {
  createViewerSlotAttributes,
  createViewerStateAttributes,
  pickCssCustomProperties,
  readViewerElementSize,
  useViewerDevelopmentLayoutWarning,
  useViewerSidebarState,
  useViewerGeometrySnapshot,
  useViewerSidebarRegistrationContext,
  VIEWER_SIDEBAR_WIDTH,
} from "./viewer-internals";
import { warnViewerDevelopmentOnce } from "./viewer-diagnostics";
import type { ViewerSidebarProps, ViewerSidebarState } from "./viewer-types";

export function ViewerSidebar({
  children,
  className,
  innerClassName,
  namespacedSlot,
  namespacedSlotNames,
  side: sideProp,
  slotNames,
  collapsible: collapsibleProp,
  width = VIEWER_SIDEBAR_WIDTH,
  style,
  id: idProp,
  ...props
}: ViewerSidebarProps) {
  const registrationContext =
    useViewerSidebarRegistrationContext("ViewerSidebar");
  const sidebarState = useViewerSidebarState("ViewerSidebar");
  const {
    defaultSidebarCollapsible,
    defaultSidebarSide,
    getRootElement,
    registerSidebar,
    rootId,
    sidebarGapTransition,
    geometryStore,
  } = registrationContext;
  const geometry = useViewerGeometrySnapshot(geometryStore);
  const reactId = React.useId();
  const instanceId = `${reactId}-viewer-sidebar-instance`;
  const generatedSidebarId = `${reactId}-viewer-sidebar`;
  const sidebarId = idProp ?? generatedSidebarId;
  const sidebarRef = React.useRef<HTMLElement | null>(null);
  const [transitionsReady, setTransitionsReady] = React.useState(false);
  const collapsible = collapsibleProp ?? defaultSidebarCollapsible;
  const side = sideProp ?? defaultSidebarSide;
  const open = collapsible === "none" ? true : sidebarState.open;
  const state: ViewerSidebarState = open ? "expanded" : "collapsed";
  const mode = sidebarState.mode;
  const visualOpen = mode === "inline" ? geometry.open : open;
  const visualState: ViewerSidebarState = visualOpen
    ? "expanded"
    : "collapsed";
  const isCollapsed = collapsible !== "none" && !open;
  const isOpening =
    collapsible !== "none" &&
    open &&
    geometry.isTransitioning;
  const frameSlot = props["data-slot"] ?? "viewer-sidebar";
  const sidebarProps = { ...props };
  delete sidebarProps["data-slot"];
  const styleWithoutWidth: React.CSSProperties = { ...style };
  delete styleWithoutWidth.width;
  const customProperties = pickCssCustomProperties(style);
  const frameStyle = {
    ...customProperties,
    "--viewer-sidebar-width": width,
  } as React.CSSProperties;
  const inlineFrameStyle = {
    ...frameStyle,
    flexBasis: `${geometry.sidebarInlineSize}px`,
    maxWidth: `${geometry.sidebarInlineSize}px`,
    width: `${geometry.sidebarInlineSize}px`,
  } as React.CSSProperties;
  const ariaLabel = sidebarProps["aria-label"];
  const ariaLabelledBy = sidebarProps["aria-labelledby"];
  const hasAccessibleName =
    (typeof ariaLabel === "string"
      ? ariaLabel.trim().length > 0
      : Boolean(ariaLabel)) ||
    (typeof ariaLabelledBy === "string"
      ? ariaLabelledBy.trim().length > 0
      : Boolean(ariaLabelledBy));

  useViewerDevelopmentLayoutWarning({
    enabled: mode === "inline" && open,
    elements: () => [getRootElement(), sidebarRef.current],
    inspect: () => {
      const rootElement = getRootElement();
      const sidebarElement = sidebarRef.current;
      const rootSize = readViewerElementSize(rootElement);
      const sidebarSize = readViewerElementSize(sidebarElement);

      if (rootSize.width > 0 && sidebarSize.width > rootSize.width) {
        warnViewerDevelopmentOnce({
          code: "viewer_sidebar_wider_than_root",
          message: "inline viewer sidebar is wider than its root.",
          rootId,
          details: {
            rootSlot: rootElement?.dataset.slot,
            rootWidth: rootSize.width,
            sidebarMode: mode,
            sidebarOpen: open,
            sidebarSide: side,
            sidebarSlot: sidebarElement?.dataset.slot,
            sidebarWidth: sidebarSize.width,
          },
        });
      }
    },
    keyParts: [
      "viewer-sidebar-wider-than-root",
      rootId,
      mode,
      open,
      side,
      width,
      getRootElement(),
      sidebarRef.current,
    ],
  });

  useMountEffect(() => {
    if (
      typeof window === "undefined" ||
      typeof window.requestAnimationFrame !== "function"
    ) {
      setTransitionsReady(true);
      return;
    }
    let secondFrame = 0;
    const firstFrame = window.requestAnimationFrame(() => {
      secondFrame = window.requestAnimationFrame(() => {
        setTransitionsReady(true);
      });
    });

    return () => {
      window.cancelAnimationFrame(firstFrame);
      window.cancelAnimationFrame(secondFrame);
    };
  });

  useKeyedLayoutEffect(
    joinEffectKey([
      collapsible,
      instanceId,
      registerSidebar,
      side,
      sidebarId,
      width,
    ]),
    () => {
      const element = sidebarRef.current;

      if (!element) {
        return;
      }

      return registerSidebar({
        collapsible,
        element,
        id: sidebarId,
        instanceId,
        side,
        width,
        widthPixels: resolveViewerSidebarWidthPixels(element, width),
      });
    },
  );

  useKeyedLayoutEffect(
    mode === "overlay" && open && !hasAccessibleName
      ? joinEffectKey([
          "viewer-overlay-sidebar-missing-accessible-name",
          rootId,
          sidebarId,
          side,
        ])
      : null,
    () => {
      warnViewerDevelopmentOnce({
        code: "viewer_overlay_sidebar_missing_accessible_name",
        message: "overlay viewer sidebar is missing an accessible name.",
        rootId,
        details: {
          sidebarId,
          sidebarMode: mode,
          sidebarSide: side,
        },
      });
    },
  );

  useKeyedLayoutEffect(
    isCollapsed
      ? joinEffectKey([
          "viewer-sidebar:move-focus-on-close",
          getRootElement,
          sidebarId,
        ])
      : null,
    () => {
      moveFocusOutOfViewerSidebar(
        sidebarRef.current,
        getRootElement(),
        sidebarId,
      );
    },
  );

  const hiddenProps = isCollapsed || isOpening
    ? ({
        "aria-hidden": true,
        inert: true,
      } as React.HTMLAttributes<HTMLElement>)
    : {};
  const namespacedSidebarStateAttributes = createViewerStateAttributes(
    registrationContext.stateNamespace,
    "sidebar",
    {
      sidebarCollapsible: collapsible,
      sidebarMode: mode,
      sidebarOpen: visualOpen,
      sidebarSide: side,
      sidebarState: visualState,
    },
  );
  const frameAttributes = {
    "data-slot": frameSlot,
    "data-collapsible": collapsible,
    "data-mode": mode,
    "data-side": side,
    "data-state": visualState,
    "data-viewer-sidebar-transitions": transitionsReady ? "ready" : undefined,
    "data-viewer-sidebar-mode": mode,
    "data-viewer-sidebar-open": visualOpen ? "true" : "false",
    "data-viewer-sidebar-state": visualState,
    "data-viewer-slot": "sidebar",
    ...createViewerSlotAttributes(
      registrationContext.stateNamespace,
      "sidebar",
      namespacedSlot,
    ),
    ...namespacedSidebarStateAttributes,
  };
  const sidebarElement = (
    <aside
      ref={sidebarRef}
      id={sidebarId}
      data-slot={slotNames?.container ?? "viewer-sidebar-container"}
      data-collapsible={collapsible}
      data-mode={mode}
      data-side={side}
      data-state={visualState}
      data-viewer-sidebar-transitions={transitionsReady ? "ready" : undefined}
      data-viewer-sidebar-mode={mode}
      data-viewer-sidebar-open={visualOpen ? "true" : "false"}
      data-viewer-sidebar-state={visualState}
      data-viewer-slot="sidebar-container"
      {...createViewerSlotAttributes(
        registrationContext.stateNamespace,
        "sidebar",
        namespacedSlotNames?.container,
      )}
      {...namespacedSidebarStateAttributes}
        className={cn(
          className,
          "z-30 flex w-(--viewer-sidebar-width) min-w-0 overflow-hidden",
          mode === "inline" &&
            "absolute inset-y-0 h-full min-w-(--viewer-sidebar-width) flex-shrink-0 transition-none",
        mode === "inline" && side === "left" && "right-0",
        mode === "inline" && side === "right" && "left-0",
        mode === "overlay" &&
          "absolute inset-y-0 transition-none data-[viewer-sidebar-transitions=ready]:transition-[translate,width,border-color] data-[viewer-sidebar-transitions=ready]:duration-150 data-[viewer-sidebar-transitions=ready]:ease-out",
        mode === "overlay" && side === "left" && "left-0",
        mode === "overlay" && side === "right" && "right-0",
        collapsible === "offcanvas" && mode === "overlay" && "shadow-lg",
        isCollapsed && "pointer-events-none",
        collapsible === "offcanvas" &&
          mode === "overlay" &&
          !visualOpen &&
          side === "left" &&
          "pointer-events-none -translate-x-full border-transparent",
        collapsible === "offcanvas" &&
          mode === "overlay" &&
          !visualOpen &&
          side === "right" &&
          "pointer-events-none translate-x-full border-transparent",
      )}
      style={
        {
          ...styleWithoutWidth,
          "--viewer-sidebar-width": width,
        } as React.CSSProperties
      }
      {...sidebarProps}
      {...hiddenProps}
    >
      <div
        data-slot={slotNames?.inner ?? "viewer-sidebar-inner"}
        data-viewer-slot="sidebar-inner"
        {...createViewerSlotAttributes(
          registrationContext.stateNamespace,
          "sidebar",
          namespacedSlotNames?.inner,
        )}
        className={cn(
          "flex h-full min-h-0 w-full min-w-0 flex-col overflow-hidden",
          innerClassName,
        )}
      >
        {children}
      </div>
    </aside>
  );

  if (mode === "inline") {
    return (
      <div
        {...frameAttributes}
        className={cn(
          "group/viewer-sidebar relative z-30 min-h-0 flex-shrink-0 overflow-hidden transition-none",
          side === "right" && "order-last",
        )}
        style={inlineFrameStyle}
      >
        {sidebarElement}
      </div>
    );
  }

  return (
    <div
      {...frameAttributes}
      className={cn(
        "group/viewer-sidebar relative z-30 min-h-0 flex-shrink-0",
        side === "right" && "order-last",
      )}
      style={frameStyle}
    >
      <div
        data-slot={slotNames?.gap ?? "viewer-sidebar-gap"}
        data-viewer-slot="sidebar-gap"
        {...createViewerSlotAttributes(
          registrationContext.stateNamespace,
          "sidebar",
          namespacedSlotNames?.gap,
        )}
        className={cn(
          "relative h-full w-(--viewer-sidebar-width) flex-shrink-0",
          sidebarGapTransition === "width" &&
            "transition-[width] duration-150 ease-out",
          collapsible === "offcanvas" && mode === "overlay" && "w-0",
        )}
      />
      {sidebarElement}
    </div>
  );
}

function moveFocusOutOfViewerSidebar(
  sidebarElement: HTMLElement | null,
  rootElement: HTMLElement | null,
  sidebarId: string,
) {
  if (typeof document === "undefined" || !sidebarElement) return;

  const activeElement = document.activeElement;
  if (
    !(activeElement instanceof HTMLElement) ||
    !sidebarElement.contains(activeElement)
  ) {
    return;
  }

  const trigger = findViewerSidebarTrigger(rootElement, sidebarId);
  if (trigger) {
    trigger.focus({ preventScroll: true });
    return;
  }

  activeElement.blur();
}

function findViewerSidebarTrigger(
  rootElement: HTMLElement | null,
  sidebarId: string,
) {
  if (!rootElement) return null;

  for (const element of rootElement.querySelectorAll<HTMLElement>(
    "[aria-controls]",
  )) {
    if (element.getAttribute("aria-controls") === sidebarId) {
      return element;
    }
  }

  return null;
}

function resolveViewerSidebarWidthPixels(element: HTMLElement, width: string) {
  const declaredWidth = parseViewerSidebarCssLength(width, element);
  if (declaredWidth !== null) return declaredWidth;

  if (typeof window !== "undefined") {
    const computedWidth = parseViewerSidebarCssLength(
      window.getComputedStyle(element).width,
      element,
    );
    if (computedWidth !== null) return computedWidth;
  }

  const measuredWidth = readViewerElementSize(element).width;
  return Number.isFinite(measuredWidth) && measuredWidth > 0
    ? measuredWidth
    : 0;
}

function parseViewerSidebarCssLength(value: string, element: HTMLElement) {
  const trimmedValue = value.trim();
  const length = Number.parseFloat(trimmedValue);
  if (!Number.isFinite(length) || length <= 0) return null;

  if (trimmedValue.endsWith("px")) return length;
  if (trimmedValue.endsWith("rem")) {
    return length * readRootFontSize();
  }
  if (trimmedValue.endsWith("em")) {
    return length * readElementFontSize(element);
  }

  return null;
}

function readRootFontSize() {
  if (typeof window === "undefined") return 16;

  const rootFontSize = Number.parseFloat(
    window.getComputedStyle(document.documentElement).fontSize,
  );
  return Number.isFinite(rootFontSize) && rootFontSize > 0
    ? rootFontSize
    : 16;
}

function readElementFontSize(element: HTMLElement) {
  if (typeof window === "undefined") return 16;

  const elementFontSize = Number.parseFloat(
    window.getComputedStyle(element).fontSize,
  );
  return Number.isFinite(elementFontSize) && elementFontSize > 0
    ? elementFontSize
    : readRootFontSize();
}

"use client";

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";
import { cn } from "@/lib/utils";

import {
  findClosestViewerBody,
  readViewerElementSize,
  useOptionalViewerSidebarRegistration,
  useOptionalViewerSurfaceMeasurementContext,
  useViewerDevelopmentLayoutWarning,
  useViewerViewportPresence,
  ViewerSurfaceMeasurementProvider,
  ViewerViewportPresenceProvider,
} from "./viewer-internals";
import { useOptionalViewerRootDiagnostics } from "./viewer-root";
import { warnViewerDevelopmentOnce } from "./viewer-diagnostics";
import { useStableElementSize } from "./viewer-measurement";
import type {
  ViewerDocumentFrameAlign,
  ViewerDocumentFrameProps,
  ViewerGeometryStore,
  ViewerSurfaceMeasurement,
  ViewerSurfaceProps,
  ViewerViewportProps,
  ViewerGeometrySnapshot,
} from "./viewer-types";

export type ViewerDocumentFrameLayout = {
  activeInlineSize: number | null;
  isTransitioning: boolean;
  maxInlineSize: number | null;
  settledInlineSize: number | null;
};

export type ViewerDocumentFrameState = {
  align: ViewerDocumentFrameAlign;
  element: HTMLDivElement | null;
  geometryStore: ViewerGeometryStore | null;
  inlineSize: number | null;
};

const ViewerDocumentFrameContext =
  React.createContext<ViewerDocumentFrameState | null>(null);

function getDocumentFrameAlignClass(align: ViewerDocumentFrameAlign) {
  switch (align) {
    case "center":
      return "mx-auto";
    case "end":
      return "ml-auto";
    case "start":
      return "mr-auto";
  }
}

export function useOptionalViewerDocumentFrame(): ViewerDocumentFrameState | null {
  return React.useContext(ViewerDocumentFrameContext);
}

export function useViewerDocumentFrameLayout({
  documentFrame,
  fallbackInlineSize,
}: {
  documentFrame: ViewerDocumentFrameState | null;
  fallbackInlineSize: number | null;
}): ViewerDocumentFrameLayout {
  const element = documentFrame?.element ?? null;
  const geometryStore = documentFrame?.geometryStore ?? null;
  const snapshotCacheRef = React.useRef<ViewerDocumentFrameLayout | null>(null);
  const subscribe = React.useCallback(
    (listener: () => void) =>
      geometryStore ? geometryStore.subscribe(listener) : () => {},
    [geometryStore],
  );
  const getSnapshot = React.useCallback(() => {
    const geometry = geometryStore?.getSnapshot() ?? null;
    const previousLayout = snapshotCacheRef.current;
    const nextLayout =
      geometry && geometry.hasMeasuredBody
        ? createViewerDocumentFrameLayoutFromGeometry({
            element,
            fallbackInlineSize,
            geometry,
          })
        : createViewerDocumentFrameFallbackLayout(fallbackInlineSize);

    if (
      previousLayout &&
      areViewerDocumentFrameLayoutsEqual(previousLayout, nextLayout)
    ) {
      return previousLayout;
    }

    snapshotCacheRef.current = nextLayout;
    return nextLayout;
  }, [element, fallbackInlineSize, geometryStore]);
  const activeLayout = React.useSyncExternalStore(
    subscribe,
    getSnapshot,
    getSnapshot,
  );
  const [settledInlineSize, setSettledInlineSize] = React.useState<
    number | null
  >(() => activeLayout.activeInlineSize);

  useKeyedLayoutEffect(
    joinEffectKey([
      "viewer-document-frame-layout:settled-inline-size",
      activeLayout.activeInlineSize,
      activeLayout.isTransitioning,
      geometryStore,
    ]),
    () => {
      if (activeLayout.isTransitioning) return;

      setSettledInlineSize((currentInlineSize) =>
        currentInlineSize === activeLayout.activeInlineSize
          ? currentInlineSize
          : activeLayout.activeInlineSize,
      );
    },
  );
  return React.useMemo(
    () => ({
      ...activeLayout,
      settledInlineSize:
        settledInlineSize ?? activeLayout.activeInlineSize ?? null,
    }),
    [activeLayout, settledInlineSize],
  );
}

export function ViewerDocumentFrame({
  align = "start",
